internal/identity/request.go:
// Package identity derives stable session identities.
//
// The 2026-10-14 Zen free-tier gate validates a descending-timestamp session
// id plus a client User-Agent, and the /inference gate 403s requests that
// carry the v1 lane's x-opencode-request header. The identity that matters
// upstream is therefore the pair (x-opencode-session, x-opencode-session-id):
// Session is the conversation-affinity key and must keep the descending layout
// minted by CanonicalSessionID; ChildSession preserves the client's own
// x-opencode-session-id when it differs, as it does for a subagent.
package identity

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math/big"
	"net/http"
	"regexp"
	"time"

	"opencode2api/internal/jsonutil"
)

// RequestIDs carries the identity headers the upstream free tier inspects.
// Session is the conversation-affinity key sent as x-opencode-session; the
// v2 lane sends ChildSession, the client's own x-opencode-session-id, as
// x-opencode-session-id so a subagent keeps its child id while affinity stays
// on the parent. The v1 lane sends Session as both headers. Message is the
// user message id the v1 lane receives as x-opencode-request; the v2 lane
// rejects that header. Request only identifies the request inside the
// gateway. Project is rendered per lane by the gateway.
type RequestIDs struct {
	Session       string
	ChildSession  string
	Request       string
	Message       string
	Project       string
	ParentSession string
}

// DeriveRequestIDs derives the upstream identity of one request. scope names
// the authenticated caller (the server key fingerprint). Every session and
// project the gateway derives itself is mixed with it, so two callers whose
// conversations begin identically never share an upstream session, sticky
// provider, preferred key, or anonymous proxy. An official OpenCode session is
// kept verbatim because the client minted it uniquely.
func DeriveRequestIDs(r *http.Request, body map[string]any, scope string) RequestIDs {
	signal := jsonutil.FirstString(
		r.Header.Get("x-opencode-session"),
		r.Header.Get("x-opencode-session-id"),
		r.Header.Get("x-session-affinity"),
		r.Header.Get("x-session-id"),
		// Codex sends its conversation id in both underscore headers.
		r.Header.Get("session_id"),
		r.Header.Get("conversation-id"),
		r.Header.Get("conversation_id"),
		jsonutil.StringAt(body, "conversation_id"),
		jsonutil.StringAt(body, "metadata", "session_id"),
		claudeCodeSessionID(jsonutil.StringAt(body, "metadata", "user_id")),
	)
	if signal == "" {
		// The system prompt plus the first user turn keeps a multi-turn
		// conversation stable as its history grows while separating
		// conversations with different beginnings.
		signal = conversationSeed(body)
	}
	if signal == "" {
		signal = jsonutil.StringAt(body, "previous_response_id")
	}
	if signal == "" || signal == `{}` {
		signal = RandomID("fallback", 16)
	}
	session := scopedSessionID(scope, signal)
	childSession := r.Header.Get("x-opencode-session-id")
	if childSession != "" {
		childSession = scopedSessionID(scope, childSession)
	}
	projectSignal := jsonutil.FirstString(r.Header.Get("x-opencode-project"), jsonutil.StringAt(body, "metadata", "project_id"))
	if projectSignal == "" {
		// A fresh project id per request. The free tier ledges its quota per
		// project id and egress, so one shared id is one shared bucket: the old
		// per-caller default arrived pre-burned on popular exits. A client that
		// names its project keeps that name.
		projectSignal = RandomProjectID()
	}
	parentSession := jsonutil.FirstString(
		r.Header.Get("x-parent-session-id"),
		jsonutil.StringAt(body, "metadata", "parent_session_id"),
	)
	if parentSession != "" {
		parentSession = scopedSessionID(scope, parentSession)
	}
	return RequestIDs{
		Session:       session,
		ChildSession:  childSession,
		Request:       RandomID("req", 16),
		Message:       UserMessageID(r, body, session),
		Project:       projectSignal,
		ParentSession: parentSession,
	}
}

// scopedSessionID keeps an official client-minted session verbatim and
// re-encodes every other signal within the caller's scope.
func scopedSessionID(scope, signal string) string {
	if isOfficialSessionID(signal) {
		return signal
	}
	if scope != "" {
		signal = scope + "\x00" + signal
	}
	return CanonicalSessionID(signal)
}

// claudeCodeSessionPattern extracts the per-session UUID Claude Code embeds in
// metadata.user_id ("user_<hash>_account_<uuid>_session_<uuid>").
var claudeCodeSessionPattern = regexp.MustCompile(`_session_([0-9A-Fa-f-]{36})$`)

// claudeCodeSessionID returns the session part of a Claude Code user id, which
// is either the underscore form above or a JSON object carrying session_id.
// The rest of the user id is per user, not per conversation, so it is never
// used as a session on its own.
func claudeCodeSessionID(userID string) string {
	if userID == "" {
		return ""
	}
	if match := claudeCodeSessionPattern.FindStringSubmatch(userID); match != nil {
		return match[1]
	}
	var value map[string]any
	if json.Unmarshal([]byte(userID), &value) == nil {
		return jsonutil.StringAt(value, "session_id")
	}
	return ""
}

// conversationSeed fingerprints how a conversation begins: its system prompt
// (Anthropic system, Responses instructions, or system/developer messages
// ahead of the first user turn) together with that first user turn. Agent
// clients often open with a boilerplate user turn such as an environment
// block, so the first user turn alone collides across unrelated users.
func conversationSeed(body map[string]any) string {
	prelude := make([]any, 0, 2)
	for _, field := range []string{"system", "instructions"} {
		if value := body[field]; value != nil {
			prelude = append(prelude, value)
		}
	}
	first, ok := firstUserTurn(body, &prelude)
	if !ok {
		return ""
	}
	encoded, err := json.Marshal(append(prelude, first))
	if err != nil {
		return ""
	}
	return string(encoded)
}

// firstUserTurn returns the content of the first user turn and appends the
// content of every system or developer message ahead of it to prelude.
func firstUserTurn(body map[string]any, prelude *[]any) (any, bool) {
	if input, ok := body["input"].(string); ok && input != "" {
		return input, true
	}
	for _, field := range []string{"messages", "input"} {
		for _, raw := range jsonutil.SliceAt(body, field) {
			item, ok := raw.(map[string]any)
			if !ok {
				continue
			}
			switch jsonutil.StringAt(item, "role") {
			case "system", "developer":
				*prelude = append(*prelude, item["content"])
			case "user":
				if content := item["content"]; content != nil {
					return content, true
				}
			}
		}
	}
	return nil, false
}

// canonicalSessionPattern matches OpenCode's canonical session format:
// "ses_" + 12 lowercase hex timestamp characters + 14 Base62 characters.
// Since 2026-09-16 the Zen free tier rejects any other session shape with
// 403 FreeTierError.
var canonicalSessionPattern = regexp.MustCompile(`^ses_[0-9a-f]{12}[0-9A-Za-z]{14}$`)

// descendingTimePartPattern matches the time part the official client mints
// with Identifier.descending(): the 48-bit value ~(ts_ms<<12|counter) in hex.
// Bitwise NOT sets the low 12 bits, so a genuine time part ends in
// 0xFFF - counter. Probing the live endpoint shows the free tier accepts
// counters 1-63 (low 12 bits 0xFC0-0xFFF) and rejects everything beyond with
// 403 FreeTierError even when the ses_ shape is right, so the pattern accepts
// exactly that window.
var descendingTimePartPattern = regexp.MustCompile(`^[0-9a-f]{9}f[c-f][0-9a-f]$`)

const base62Alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"

// bootNonce separates the sessions one gateway process derives from those its
// earlier runs derived. It is minted once per process and mixed into every
// synthesized session, so restarting the daemon re-mints the upstream session
// ids for the same conversations, while a single run keeps one stable id per
// conversation. Official client sessions bypass it and stay verbatim.
var bootNonce = mintBootNonce()

// mintBootNonce returns the per-process session salt. It panics when the
// system random source fails.
func mintBootNonce() []byte {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		panic("crypto/rand failed: " + err.Error())
	}
	return buf
}

// CanonicalSessionID returns signal unchanged when it already carries an
// official OpenCode session minted by the client's Identifier.descending()
// (preserving upstream prompt-cache affinity). Any other downstream identity
// (UUIDs, foreign client sessions, legacy gateway sessions, conversation
// seeds) is re-encoded into that exact layout — inverted 48-bit millisecond
// timestamp with counter 1, so the low 12 hex digits are ffe — keeping one
// stable session per conversation for the life of the process. The upstream
// free tier also ties a session id to its risk/quota bookkeeping, so the
// re-encoding is salted with bootNonce: a restart yields fresh ids instead of
// resuming whatever the previous run's exits were charged for. A re-encoded
// session passes the free tier's encoding check where the raw hash shape was
// rejected with 403 FreeTierError.
//
// The timestamp must also stay plausible. The free tier derives a risk window
// from it: a session dated more than about a year from now, in either
// direction, is answered with HTTP 429 "Free usage limit reached" — the same
// message a genuinely exhausted IP receives — so a hash-derived timestamp
// (which landed in 1970) made every free request fail however many WARP exits
// were rotated. The encoding below therefore draws the timestamp from a slow
// clock instead of the hash: today's UTC midnight minus a hash-derived offset
// of at most sessionTimestampWindow. The id stays stable for a whole day, which
// is all the affinity a live conversation needs, and its date never leaves the
// window the upstream accepts.
func CanonicalSessionID(signal string) string {
	if isOfficialSessionID(signal) {
		return signal
	}
	hasher := sha256.New()
	hasher.Write([]byte("ses\x00"))
	hasher.Write(bootNonce)
	hasher.Write([]byte{0})
	hasher.Write([]byte(signal))
	sum := hasher.Sum(nil)
	timePart := descendingTimePart(time.Now(), sum[:6])
	randomPart := base62Fixed(new(big.Int).SetBytes(sum[6:16]), 14)
	return "ses_" + timePart + randomPart
}

// isOfficialSessionID reports whether signal is a session minted by the
// official client's Identifier.descending(). A value with the right ses_ shape
// but a foreign encoding (raw hash or ascending ID) is not official.
func isOfficialSessionID(signal string) bool {
	return canonicalSessionPattern.MatchString(signal) && descendingTimePartPattern.MatchString(signal[4:16])
}

// sessionTimestampWindow bounds how far before today a synthesized session's
// timestamp may fall. The upstream accepts a date roughly a year away in either
// direction and rejects anything beyond with HTTP 429, so a month leaves room
// for clock skew and long-lived processes while never approaching the edge.
const sessionTimestampWindow = 30 * 24 * time.Hour

// descendingTimePart renders a plausible recent timestamp in the official
// client's Identifier.descending() layout: a 36-bit timestamp shifted into the
// top of a 48-bit word, ORed with counter 1, then bitwise-NOT-ed so the low 12
// hex digits read ffe. The hash only picks the offset within
// sessionTimestampWindow; it never supplies the date itself.
func descendingTimePart(now time.Time, hash []byte) string {
	window := uint64(sessionTimestampWindow / time.Millisecond)
	offset := (uint64(hash[0])<<24 | uint64(hash[1])<<16 | uint64(hash[2])<<8 | uint64(hash[3])) % window
	base := now.UTC().Truncate(24 * time.Hour).Add(-time.Duration(offset) * time.Millisecond)
	current := uint64(base.UnixMilli())<<12 | 1
	inverted := ^current & 0xFFFFFFFFFFFF
	return hex.EncodeToString([]byte{
		byte(inverted >> 40), byte(inverted >> 32), byte(inverted >> 24),
		byte(inverted >> 16), byte(inverted >> 8), byte(inverted),
	})
}

// base62Fixed renders n in the Base62 alphabet, zero-padded to width
// characters. It consumes n.
func base62Fixed(n *big.Int, width int) string {
	base := big.NewInt(62)
	out := make([]byte, width)
	remainder := new(big.Int)
	for i := width - 1; i >= 0; i-- {
		n.DivMod(n, base, remainder)
		out[i] = base62Alphabet[remainder.Int64()]
	}
	return string(out)
}

// RandomID returns prefix + "_" + size random bytes in hex. It panics when the
// system random source fails.
func RandomID(prefix string, size int) string {
	buf := make([]byte, size)
	if _, err := rand.Read(buf); err != nil {
		panic(fmt.Sprintf("crypto/rand failed: %v", err))
	}
	return prefix + "_" + hex.EncodeToString(buf)
}

// RandomProjectID returns a project id in the shape the official CLI sends: the
// 40-character hex of a git root commit. It is minted per request when the
// client names no project, because the free tier ledges quota per project id
// and egress together. It panics when the system random source fails.
func RandomProjectID() string {
	buf := make([]byte, 20)
	if _, err := rand.Read(buf); err != nil {
		panic(fmt.Sprintf("crypto/rand failed: %v", err))
	}
	return hex.EncodeToString(buf)
}

internal/gateway/upstream.go:
package gateway

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"slices"
	"sort"
	"strconv"
	"strings"
	"time"

	"opencode2api/internal/config"
	"opencode2api/internal/httpx"
	"opencode2api/internal/identity"
	"opencode2api/internal/jsonutil"
	"opencode2api/internal/models"
	wire "opencode2api/internal/protocol"
	"opencode2api/internal/telemetry"
)

// DebugKeyOverride pins one inference request to a single configured upstream
// key so the Playground can exercise that key in isolation.
type DebugKeyOverride struct {
	Tier  config.Tier
	KeyID string
}

type debugKeyOverrideContextKey struct{}

type diagnosticContextKey struct{}

// WithDiagnosticRequest marks ctx as a Playground diagnostic request. It uses
// the production routing and transports, but its outcomes never update key
// cooldowns, proxy health or bindings, and its traffic is accounted to the
// Playground server key rather than the key that authenticated it.
func WithDiagnosticRequest(ctx context.Context) context.Context {
	return context.WithValue(ctx, diagnosticContextKey{}, true)
}

func isDiagnosticRequest(ctx context.Context) bool {
	diagnostic, _ := ctx.Value(diagnosticContextKey{}).(bool)
	return diagnostic
}

// WithDebugKeyOverride marks ctx as a diagnostic request (see
// WithDiagnosticRequest) pinned to override: the request is routed to
// override.Tier only and sent once through that key, with no failover (see
// doSelectedKeyUpstream). An override without a KeyID is ignored.
func WithDebugKeyOverride(ctx context.Context, override DebugKeyOverride) context.Context {
	return context.WithValue(WithDiagnosticRequest(ctx), debugKeyOverrideContextKey{}, override)
}

// RelaySelection names one configured upstream relay (proxy) so a diagnostic
// request can be pinned to it. Index is the position in the configured proxy
// list, Name is the proxy URL; supplying both requires them to agree. Either
// alone is enough, and an empty selection means normal routing.
type RelaySelection struct {
	Index *int   `json:"index,omitempty"`
	Name  string `json:"name,omitempty"`
}

// Empty reports whether the selection names no relay.
func (r RelaySelection) Empty() bool {
	return r.Index == nil && r.Name == ""
}

type relayOverrideContextKey struct{}

// WithRelayOverride pins one inference request to a single configured relay,
// on every tier: the anonymous lane walks exactly that exit and a key request
// is sent through that proxy, each with a single attempt and no failover.
// Session minting, system prompt, tool shaping and the transport stay the
// production path. The request is marked diagnostic, so the pinned attempt
// changes no cooldown, proxy health or IP-block state and cannot poison the
// relays it is meant to measure.
func WithRelayOverride(ctx context.Context, selection RelaySelection) context.Context {
	return context.WithValue(WithDiagnosticRequest(ctx), relayOverrideContextKey{}, selection)
}

func relayOverrideFrom(ctx context.Context) (RelaySelection, bool) {
	selection, ok := ctx.Value(relayOverrideContextKey{}).(RelaySelection)
	if !ok || selection.Empty() {
		return RelaySelection{}, false
	}
	return selection, true
}

// RelayNames lists the configured relays in configuration order, with any
// credentials redacted, so a caller can name one by index or by URL.
func (g *Gateway) RelayNames() []string {
	if g.transports == nil {
		return nil
	}
	names := make([]string, 0, len(g.transports.items))
	for _, transport := range g.transports.items {
		if transport != nil {
			names = append(names, config.RedactURL(transport.name))
		}
	}
	return names
}

// RelayProxy resolves a selection against the configured proxies. It reports
// false when nothing matches, so a typo surfaces as an error instead of a
// silent fallback to normal routing.
func (g *Gateway) RelayProxy(selection RelaySelection) (*proxyTransport, bool) {
	if g.transports == nil {
		return nil, false
	}
	index := -1
	if selection.Index != nil {
		index = *selection.Index
		if index < 0 || index >= len(g.transports.items) {
			return nil, false
		}
	}
	for i, transport := range g.transports.items {
		if transport == nil {
			continue
		}
		if index >= 0 && i != index {
			continue
		}
		if selection.Name != "" && transport.name != selection.Name && config.RedactURL(transport.name) != selection.Name {
			continue
		}
		return transport, true
	}
	return nil, false
}

var errRelayNotFound = errors.New("relay does not match any configured proxy")

func debugKeyOverrideFrom(ctx context.Context) (DebugKeyOverride, bool) {
	override, ok := ctx.Value(debugKeyOverrideContextKey{}).(DebugKeyOverride)
	return override, ok && override.KeyID != ""
}

// doUpstream sends one inference request through the anonymous and key tiers
// (see doUpstreamTiers) and returns the response, whose body the caller must
// close, together with the route that produced it. It repairs one known
// failure: when the returned response is a 400 reporting a stale reasoning
// reference, it replays the request once with those references stripped, and
// returns the original 400 if the replay does not succeed. A 400 body is
// buffered (up to 1 MiB) so it can be read again. Debug key overrides skip the
// replay so the Playground sees the selected key's own answer.
func (g *Gateway) doUpstream(ctx context.Context, route models.Route, bodies map[config.Tier][]byte, ids identity.RequestIDs) (*http.Response, models.Route, error) {
	resp, effectiveRoute, attempts, err := g.doUpstreamTiers(ctx, route, bodies, ids, 0)
	if _, selected := debugKeyOverrideFrom(ctx); selected || !effectiveRoute.Anonymous && g.tierOAuth(effectiveRoute.Tier) != nil {
		return resp, effectiveRoute, err
	}
	if err != nil || resp == nil || resp.StatusCode != http.StatusBadRequest {
		return resp, effectiveRoute, err
	}
	origBody := resp.Body
	errBody, readErr := io.ReadAll(io.LimitReader(origBody, 1<<20))
	// The network body is always drained and closed here so its connection
	// can be reused, for instance by the retry below; downstream receives a
	// fresh in-memory reader over the cached bytes instead.
	httpx.DrainAndClose(origBody)
	if readErr != nil {
		resp.Body = io.NopCloser(bytes.NewReader(errBody))
		return resp, effectiveRoute, nil
	}
	// Restore the body so downstream error handling still sees the original
	// payload when no retry happens below.
	resp.Body = io.NopCloser(bytes.NewReader(errBody))
	// Log a capped snippet of the upstream error body so the 400 class is
	// visible without dumping full payloads. Bodies stay out of attempt
	// records, and the snippet is scrubbed of configured secrets before it is
	// logged.
	if len(errBody) > 0 {
		redactor := config.SecretRedactor()
		redactor.Replace(g.cfg)
		snippet := redactor.String(string(errBody))
		if len(snippet) > 240 {
			snippet = snippet[:240]
		}
		g.logger.Info("upstream error returned or retried", "component", "upstream", "event", "upstream_error_body", "request_id", ids.Request, "model", route.ID, "status", resp.StatusCode, "snippet", snippet)
	}
	if !isStaleReasoningReference(errBody) {
		return resp, effectiveRoute, nil
	}
	stripped, changed := stripStaleReasoningInputs(effectiveRoute, bodies)
	if !changed {
		return resp, effectiveRoute, nil
	}
	// The referenced reasoning items belong to an upstream chain this session
	// can no longer address (e.g. an interrupted stream). Replay once without
	// them instead of failing the client request outright. Attempt numbering
	// continues from the first round so monitoring never shows duplicate attempt
	// numbers for one request.
	//
	// The client's session is deliberately preserved: it carries key/proxy
	// affinity and upstream session correlation. Minting a fresh session made
	// the replay land on a different node with a cold prompt cache and detached
	// the reply from the chain the client still holds; the stale references are
	// already removed from the payload itself.
	g.logger.Info("retrying upstream without stale reasoning references", "component", "upstream", "event", "reasoning_reference_retry", "request_id", ids.Request, "model", route.ID, "tier", effectiveRoute.Tier, "attempt_offset", attempts)
	retryResp, retryRoute, _, retryErr := g.doUpstreamTiers(ctx, effectiveRoute, stripped, ids, attempts)
	if retryErr != nil || retryResp == nil || retryResp.StatusCode/100 != 2 {
		retryStatus := 0
		if retryResp != nil {
			retryStatus = retryResp.StatusCode
			httpx.DrainAndClose(retryResp.Body)
		}
		g.logger.Warn("reasoning reference retry failed; returning original error", "component", "upstream", "event", "reasoning_reference_retry_failed", "request_id", ids.Request, "model", route.ID, "tier", effectiveRoute.Tier, "error", retryErr, "retry_status", retryStatus)
		fallback := *resp
		fallback.Body = io.NopCloser(bytes.NewReader(errBody))
		return &fallback, effectiveRoute, nil
	}
	return retryResp, retryRoute, nil
}

// isStaleReasoningReference reports whether an upstream 400 body describes a
// reasoning item/reference the server no longer recognizes, such as
// "Referenced reasoning item 'rs_...' was not found or has expired".
// Generic validation errors that merely mention reasoning (e.g. "unknown
// reasoning field") must NOT match, so both the target phrase and the
// gone/expired marker are required.
func isStaleReasoningReference(body []byte) bool {
	text := strings.ToLower(string(body))
	if !strings.Contains(text, "reasoning item") && !strings.Contains(text, "reasoning reference") {
		return false
	}
	for _, marker := range []string{"not found", "expir", "does not exist", "no longer"} {
		if strings.Contains(text, marker) {
			return true
		}
	}
	return false
}

// stripStaleReasoningInputs removes server-issued reasoning references from
// Responses-protocol upstream payloads: replayed "reasoning" input items and
// any previous_response_id chain link. Other tiers/protocols are passed
// through untouched. It reports whether any payload actually changed.
func stripStaleReasoningInputs(route models.Route, bodies map[config.Tier][]byte) (map[config.Tier][]byte, bool) {
	changed := false
	out := make(map[config.Tier][]byte, len(bodies))
	for tier, body := range bodies {
		if len(body) == 0 || route.ProtocolFor(tier) != wire.Responses {
			out[tier] = body
			continue
		}
		var payload map[string]any
		if err := json.Unmarshal(body, &payload); err != nil {
			out[tier] = body
			continue
		}
		tierChanged := false
		if _, ok := payload["previous_response_id"]; ok {
			delete(payload, "previous_response_id")
			tierChanged = true
		}
		if raw, ok := payload["input"].([]any); ok {
			kept := make([]any, 0, len(raw))
			for _, item := range raw {
				if m, ok := item.(map[string]any); ok && jsonutil.StringAt(m, "type") == "reasoning" {
					tierChanged = true
					continue
				}
				kept = append(kept, item)
			}
			if tierChanged {
				payload["input"] = kept
			}
		}
		if !tierChanged {
			out[tier] = body
			continue
		}
		encoded, err := jsonutil.Marshal(payload)
		if err != nil {
			out[tier] = body
			continue
		}
		out[tier] = encoded
		changed = true
	}
	return out, changed
}

// doUpstreamTiers runs one routing pass and reports the response, the route
// that produced it, and the attempt count so far (attemptOffset plus the
// attempts made here). A debug key override short-circuits to that single key
// and reports its attempt including attemptOffset. Otherwise an anonymous
// route first tries the free tier, then every tier in route.KeyTiers order (a
// keyed Zen or Go route without KeyTiers uses its own tier) until one returns
// 2xx. Without a success it returns the last HTTP response, whose body is still
// open, in preference to the last error. Once ctx is done it no longer enters
// the key tiers.
func (g *Gateway) doUpstreamTiers(ctx context.Context, route models.Route, bodies map[config.Tier][]byte, ids identity.RequestIDs, attemptOffset int) (response *http.Response, resultRoute models.Route, resultAttempts int, resultErr error) {
	var lastResponse *http.Response
	defer func() {
		if lastResponse != nil && lastResponse != response {
			httpx.DrainAndClose(lastResponse.Body)
		}
	}()
	var lastErr error
	effectiveRoute := route
	attempts := attemptOffset
	g.dumpOutboundBodies(route, bodies, ids, attemptOffset)
	if override, selected := debugKeyOverrideFrom(ctx); selected {
		resp, err, used := g.doSelectedKeyUpstream(ctx, route, bodies, ids, override, attemptOffset)
		return resp, route, attemptOffset + used, err
	}
	blocked := false
	if route.Anonymous {
		resp, err, used := g.doAnonymousUpstream(ctx, route, bodies, ids, attempts)
		attempts += used
		lastResponse, lastErr = resp, err
		if errors.Is(ctx.Err(), context.Canceled) {
			return nil, effectiveRoute, attempts, ctx.Err()
		}
		if err == nil && resp != nil && resp.StatusCode/100 == 2 {
			return resp, route, attempts, nil
		}
		if errors.Is(err, errDeterministicClientRejection) {
			// The request itself was rejected. Another lane or key gets the same
			// answer, and retrying only buries this error under the next one, so
			// hand the upstream 4xx back as the response (nil error) and let the
			// normal error path forward its status and body unchanged.
			g.logger.Warn("upstream rejected the request; not retrying on other tiers", "component", "upstream", "event", "deterministic_rejection", "request_id", ids.Request, "attempts", attempts, "model", route.ID)
			return lastResponse, effectiveRoute, attempts, nil
		}
		if errors.Is(err, errFreeTierIPBlocked) {
			// The free tier flagged the egress IP. The Zen key tier uses the
			// same free gateway and gets the same answer; the Go tier is
			// authenticated and is not subject to the free-tier IP gate, so
			// keep it available below.
			blocked = true
			g.logger.Warn("free tier blocked the egress IP; skipping the Zen key tier", "component", "upstream", "event", "free_tier_ip_blocked", "request_id", ids.Request, "attempts", attempts)
		}
		if len(route.KeyTiers) > 0 {
			g.logger.Debug("anonymous request did not succeed; entering preferred key tiers", "component", "upstream", "event", "anonymous_fallback", "request_id", ids.Request, "attempts", attempts, "key_tiers", route.KeyTiers)
		}
	}
	if ctx.Err() != nil {
		// The anonymous phase already consumed the request budget. Entering the
		// authenticated tiers here would only fire instant attempts against a
		// dead context, cooling keys that were never really tried.
		if errors.Is(ctx.Err(), context.Canceled) {
			return nil, effectiveRoute, attempts, ctx.Err()
		}
		if lastResponse != nil {
			return lastResponse, effectiveRoute, attempts, nil
		}
		if lastErr == nil {
			lastErr = ctx.Err()
		}
		return nil, effectiveRoute, attempts, lastErr
	}

	keyTiers := route.KeyTiers
	if !route.Anonymous && len(keyTiers) == 0 && (route.Tier == config.TierZen || route.Tier == config.TierGo) {
		keyTiers = []config.Tier{route.Tier}
	}
	for _, tier := range keyTiers {
		if blocked && tier == config.TierZen {
			g.logger.Debug("skipping the Zen key tier after an IP block", "component", "upstream", "event", "free_tier_ip_blocked", "request_id", ids.Request, "tier", tier)
			continue
		}
		keyRoute := route
		keyRoute.Tier = tier
		keyRoute.Anonymous = false
		keyRoute.Protocol = route.ProtocolFor(tier)
		bufferRetryResponse(lastResponse)
		resp, err, used := g.doKeyUpstream(ctx, keyRoute, bodies, ids, attempts)
		attempts += used
		lastResponse = replaceRetryResponse(lastResponse, resp)
		if resp != nil {
			effectiveRoute = keyRoute
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return nil, effectiveRoute, attempts, ctx.Err()
		}
		if err == nil && resp != nil && resp.StatusCode/100 == 2 {
			return resp, keyRoute, attempts, nil
		}
		if resp != nil {
			if isDeterministicClientResponse(resp.StatusCode, peekResponseBody(resp)) {
				// Same request-level rejection as on the anonymous lane: no
				// other tier can fix it, so return it as is.
				g.logger.Warn("upstream rejected the request; not trying other tiers", "component", "upstream", "event", "deterministic_rejection", "request_id", ids.Request, "attempts", attempts, "tier", keyRoute.Tier, "status", resp.StatusCode)
				return resp, keyRoute, attempts, nil
			}
		}
		if err != nil {
			lastErr = err
		}
	}
	if errors.Is(ctx.Err(), context.Canceled) {
		return nil, effectiveRoute, attempts, ctx.Err()
	}
	if blocked {
		// The request never left the free tier's IP block: keep the block as
		// the client-facing cause even if a Go fallback also failed, and close
		// the last free-tier response whose body the handler will not forward.
		return nil, effectiveRoute, attempts, errFreeTierIPBlocked
	}
	if lastResponse != nil {
		return lastResponse, effectiveRoute, attempts, nil
	}
	if lastErr == nil {
		lastErr = errors.New("no usable upstream route")
	}
	return nil, effectiveRoute, attempts, lastErr
}

// defaultMaxAnonymousExits caps how many static proxies one request walks when
// performance.max_anonymous_exits is zero. Without a cap, a request that every
// exit rejects (403/429) scans the whole proxy list, up to two lanes per exit,
// and can spend minutes before failing over.
const defaultMaxAnonymousExits = 8

// maxAnonymousExits returns the configured cap, or the built-in default when
// the operator left the setting unset.
func (g *Gateway) maxAnonymousExits() int {
	if g != nil && g.cfg.Performance.MaxAnonymousExits > 0 {
		return g.cfg.Performance.MaxAnonymousExits
	}
	return defaultMaxAnonymousExits
}

// doAnonymousUpstream walks the session's anonymous proxy cursor. Each static
// proxy is tried at most once, up to performance.max_anonymous_exits proxies;
// rotating #pool proxies may be drawn again until Retry.MaxAttempts proxies
// were used. For each proxy it tries the upstreams in anonymousUpstreams
// order: the configured v2 /inference upstream (Upstream.Anonymous) only, since
// the v1 lane fallback is retired and commented out there. Any failure,
// including an HTTP error response, advances to the next upstream or proxy; a
// proxy-route failure, or a proxy marked unhealthy, skips that proxy's
// remaining upstreams. Only a successful response ends the anonymous phase;
// exhausting the proxy cursor returns control to the preferred authenticated
// tiers. It returns the last response (body still open), else the last error,
// plus the number of attempts made.
func (g *Gateway) doAnonymousUpstream(ctx context.Context, route models.Route, bodies map[config.Tier][]byte, ids identity.RequestIDs, attemptOffset int) (response *http.Response, resultErr error, resultAttempts int) {
	if g.usesWARP(route.ID, config.TierZen, true) {
		return g.doWarpAnonymousUpstream(ctx, route, bodies, ids, attemptOffset)
	}
	// The breaker holds the lane shut for an hour-scale window after repeated
	// failures: poking a flagged upstream again would only extend the block.
	if !g.anonymous.AllowAttempt() {
		return nil, errAnonymousLanePaused, 0
	}
	defer g.anonymous.ReleaseProbe()
	var lastResponse *http.Response
	defer func() {
		if lastResponse != nil && lastResponse != response {
			httpx.DrainAndClose(lastResponse.Body)
		}
	}()
	var lastErr error
	// blocked records that some exit is under the free tier's IP block. The
	// result then reports errFreeTierIPBlocked even when no exit was left to
	// try, so the caller can report the block instead of a generic failure.
	blocked := false
	// halted records that the upstream rejected the request itself. The result
	// then reports errDeterministicClientRejection so the caller keeps this
	// 4xx instead of replacing it with a later tier's answer.
	halted := false
	cursor := g.anonymous.CursorForOffset(ids.Session, attemptOffset)
	limit := min(g.anonymous.Len(), g.maxAnonymousExits())
	if g.anonymous.HasPool() && g.cfg.Retry.MaxAttempts > limit {
		limit = g.cfg.Retry.MaxAttempts
	}
	// A relay-pinned diagnostic sends exactly one attempt through the chosen
	// exit, so the answer describes that relay alone. An unresolvable relay is
	// an error rather than a silent fallback, because a typo would otherwise
	// read as a relay verdict.
	if selection, ok := relayOverrideFrom(ctx); ok {
		proxy, found := g.RelayProxy(selection)
		if !found {
			return nil, errRelayNotFound, 0
		}
		cursor = g.anonymous.CursorForProxy(proxy)
		limit = 1
	}
	proxies := 0
	attempts := 0
	rawBody := bodies[config.TierZen]
	if len(rawBody) == 0 {
		return nil, errors.New("no prepared Zen request body"), 0
	}
	isTitle := isTitleGenerationBody(rawBody)
	if isTitle {
		limit = 1
	}
	// The anonymous free tier only serves agent-shaped streaming requests
	// carrying the required tool definitions (anything else is rejected with 403
	// FreeTierError). Normalize the wire body per upstream gate (v1 /zen vs v2
	// /inference); the gateway collapses the stream back when the downstream
	// client asked for a plain JSON reply. Key tiers shape their own bodies
	// (see shapeKeyBody).
	protocol := route.ProtocolFor(config.TierZen)
	upstreams := g.anonymousUpstreams()
	preparedBodies := make([][]byte, len(upstreams))
	toolRenames := make([]*wire.ToolRenames, len(upstreams))
	for i, baseURL := range upstreams {
		preparedBodies[i], toolRenames[i] = prepareAnonymousBody(rawBody, protocol, models.IsV1Upstream(baseURL), g.requestEnvironment(ctx))
	}
	for proxies < limit {
		if ctx.Err() != nil {
			// The request-level budget is already gone. Stop scanning instead
			// of firing attempts that cannot succeed and then recording them
			// as failures against proxies that were never really tried.
			if lastErr == nil {
				lastErr = ctx.Err()
			}
			break
		}
		node := cursor.Next()
		if node == nil {
			// Nothing usable is left. If that is because every exit is under
			// the free tier's block, report the block rather than the generic
			// no-proxy error, so the caller can try the authenticated Go tier
			// or answer with the block itself.
			blocked = g.anonymous.blockedExits(time.Now())
			break
		}
		proxies++
		var nodeResp *http.Response
		var nodeErr error
		for index, baseURL := range upstreams {
			if ctx.Err() != nil {
				if lastErr == nil && lastResponse == nil {
					lastErr = ctx.Err()
				}
				break
			}
			setRequestShape(ctx, false, toolRenames[index])
			attempts++
			if meta := telemetry.MetaFromContext(ctx); meta != nil {
				meta.Attempts = attemptOffset + attempts
				meta.Tier = string(config.TierZen)
			}
			bufferRetryResponse(lastResponse)
			req, err := upstreamRequest(ctx, baseURL, protocol, preparedBodies[index], ids, anonymousZenKey)
			if err != nil {
				return nil, err, attempts
			}
			if node.proxy.pool {
				req.Close = true
			}
			setRequestCredential(ctx, config.TierZen, "anonymous", "anonymous", true, node.proxy)
			started := time.Now()
			resp, err := doInferenceAttempt(g.inferenceClient(node.proxy, baseURL, route.ID), req, time.Duration(g.cfg.Performance.FirstEventTimeoutSeconds)*time.Second, g.attemptTimeout)
			duration := time.Since(started)
			lastResponse = replaceRetryResponse(lastResponse, resp)
			if ctx.Err() != nil {
				// The parent budget expired while this attempt was in flight. Its
				// outcome says nothing about this proxy, so record nothing and stop
				// scanning.
				lastErr = err
				if lastErr == nil && lastResponse == nil {
					lastErr = ctx.Err()
				}
				break
			}
			nodeResp, nodeErr = resp, err
			g.recordUpstreamAttempt(ctx, route, ids, attemptOffset+attempts, "anonymous", "anonymous", true, node.proxy, resp, err, duration)
			if err == nil && resp.StatusCode/100 == 2 {
				g.observeAnonymousResult(ctx, node, resp, nil)
				g.logger.Debug("anonymous upstream accepted request", "component", "upstream", "event", "anonymous_attempt_succeeded", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "key_id", "anonymous", "channel", "anonymous", "anonymous", true, "proxy", config.RedactURL(node.proxy.name), "status", resp.StatusCode, "duration_ms", duration.Milliseconds())
				return resp, nil, attempts
			}
			lastErr = asProxyUnavailable(node.proxy, err)
			if err != nil {
				g.logger.Debug("anonymous transport attempt failed", "component", "upstream", "event", "anonymous_attempt_transport_failed", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "key_id", "anonymous", "channel", "anonymous", "anonymous", true, "proxy", config.RedactURL(node.proxy.name), "duration_ms", duration.Milliseconds(), "error", err)
				if isProxyFailure(err) {
					break
				}
			} else if peekNetworkAbuseBlock(resp) {
				// The free tier flagged this egress IP. The other lane leaves
				// from the same IP and would answer the same way, so cool the
				// exit and move on to another one instead of adding attempts
				// that only lengthen the penalty. The body is restored, so the
				// caller still forwards the upstream error.
				node.proxy.markBlocked(time.Now().Add(g.freeTierBlockTTL()))
				lastErr = errFreeTierIPBlocked
				blocked = true
				g.logger.Warn("free tier blocked the egress IP; cooling the exit", "component", "upstream", "event", "free_tier_ip_blocked", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "proxy", config.RedactURL(node.proxy.name), "block_for", g.freeTierBlockTTL().String())
				break
			} else if isDeterministicClientResponse(resp.StatusCode, peekResponseBody(resp)) {
				// The request is too long, malformed, or otherwise invalid on
				// every lane. Stop here and hand this 4xx to the client.
				lastErr = errDeterministicClientRejection
				halted = true
				g.logger.Warn("upstream rejected the request; not trying other upstreams", "component", "upstream", "event", "deterministic_rejection", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "status", resp.StatusCode, "duration_ms", duration.Milliseconds())
				break
			} else {
				g.logger.Debug("anonymous upstream returned an error response; trying the next upstream or proxy", "component", "upstream", "event", "anonymous_attempt_response_failed", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "key_id", "anonymous", "channel", "anonymous", "anonymous", true, "proxy", config.RedactURL(node.proxy.name), "status", resp.StatusCode, "duration_ms", duration.Milliseconds())
			}
			if index+1 < len(upstreams) && !node.proxy.healthy.Load() {
				break
			}
		}
		if halted {
			// A request-level rejection is identical on every exit: another
			// proxy cannot shorten the context or repair the payload. Keep the
			// response and let the caller forward it instead of sending the
			// same request through every remaining exit.
			g.anonymous.NoteNeutral()
			break
		}
		if ctx.Err() != nil {
			break
		}
		g.observeAnonymousResult(ctx, node, nodeResp, nodeErr)
		if g.anonymous.Open() {
			// This attempt tripped the breaker (or another request did):
			// continuing the walk would keep probing a lane that is now
			// paused.
			break
		}
	}
	if errors.Is(ctx.Err(), context.Canceled) {
		return nil, ctx.Err(), attempts
	}
	// Every configured exit is under the same IP block: another request
	// cannot reach a working exit, so pause the lane instead of repeating the
	// 403 walk until the exit cool-downs expire.
	if blocked && g.anonymous.blockedExits(time.Now()) {
		if pause, tripped := g.anonymous.ForceOpen(); tripped {
			g.logger.Warn("anonymous lane circuit breaker opened", "component", "upstream", "event", "anonymous_breaker_open", "reason", "all_exits_blocked", "request_id", ids.Request, "paused_for", pause.String())
		}
	}
	if isTitle {
		if fallback := titleFallback(g.logger, route.ID, rawBody, lastResponse, lastErr); fallback != nil {
			lastResponse = nil
			return fallback, nil, attempts
		}
	}
	if lastResponse != nil {
		// The caller keeps and forwards this response; a block or a
		// deterministic rejection only changes the error so the keyed tiers
		// are skipped. A request-level rejection wins over a block seen on an
		// earlier exit: it is the error the client can act on, and forwarding
		// the block instead would hide the real cause.
		if halted {
			return lastResponse, errDeterministicClientRejection, attempts
		}
		if blocked {
			return lastResponse, errFreeTierIPBlocked, attempts
		}
		return lastResponse, nil, attempts
	}
	if blocked {
		return nil, errFreeTierIPBlocked, attempts
	}
	if lastErr == nil {
		lastErr = errors.New("no healthy anonymous proxies available")
		if !g.transports.hasHealthy() {
			lastErr = fmt.Errorf("no healthy anonymous proxies available: %w", errProxyUnavailable)
		}
	}
	return nil, lastErr, attempts
}

// anonymousUpstreams returns the ordered base URLs for the keyless free tier.
// Only the v2 /inference origin is used: the 1.x /zen lane was retired for free
// models, so the v1 fallback is commented out rather than called. The code is
// kept for a revert; uncommenting the two lines marked below restores the old
// order (v2 first, v1 as fallback).
func (g *Gateway) anonymousUpstreams() []string {
	// v1 := strings.TrimRight(models.V1Base, "/")
	primary := strings.TrimRight(g.cfg.Upstream.Anonymous, "/")
	if primary == "" {
		// Config normalization fills this; keep the v2 default for a zero-value
		// config so this never falls through to the retired v1 lane.
		primary = "https://opencode.ai/inference"
	}
	return []string{primary}
	// return []string{g.cfg.Upstream.Anonymous, models.V1Base}
}

// inferenceClient picks the client of proxy for a request for model to
// baseURL. Free-model traffic to the /zen and /inference lanes goes through
// the Bun client (see httpx.BunTransport), whose TLS ClientHello and HTTP/1.1
// header layout match the runtime of the official OpenCode clients; every
// other request, including the Go tier (/zen/go), keeps the regular client.
func (g *Gateway) inferenceClient(proxy *proxyTransport, baseURL, model string) *http.Client {
	lane := strings.ToLower(strings.TrimRight(strings.TrimSpace(baseURL), "/"))
	if g.catalog.IsFreeModel(model) && (models.IsV1Upstream(baseURL) || strings.HasSuffix(lane, "/inference")) {
		return proxy.bun
	}
	return proxy.client
}

// prepareAnonymousBody returns body normalized for the free tier alongside the
// tool renames the response must restore. The body is forced to stream (keeping
// Chat usage reporting on), carries the official CLI system prompt, and its
// tools are renamed and completed for the lane v1 selects; an unchanged body is
// returned as is.
//
// Every named client tool becomes an opaque wire name (see
// protocol.ClientToolWireName: a client tool name that survives on the wire is
// what the free tier refuses) and the full official set for the lane is
// appended, so the request looks like an official CLI session on both the v1
// (/zen) and v2 lanes. System One payloads are decision requests, not agent
// traffic, so they are forwarded verbatim, as is a body that is not a JSON
// object.
func prepareAnonymousBody(body []byte, protocol wire.Protocol, v1 bool, environment *config.PromptEnvironmentConfig) ([]byte, *wire.ToolRenames) {
	if protocol == wire.SystemOne {
		return body, nil
	}
	var payload map[string]any
	if err := json.Unmarshal(body, &payload); err != nil {
		return body, nil
	}
	isTitle := isTitleGenerationRequest(payload)
	changed := false
	if streaming, ok := payload["stream"].(bool); !ok || !streaming {
		payload["stream"] = true
		changed = true
	}
	if ensureAnonymousChatUsage(payload, protocol) {
		changed = true
	}
	if injectOfficialPrompt(payload, protocol, v1, environment) {
		changed = true
	}
	var renames *wire.ToolRenames
	if !isTitle {
		platform := ""
		if environment != nil {
			platform = environment.Platform
		}
		var toolsChanged bool
		renames, toolsChanged = renameAndCompleteTools(payload, protocol, v1, platform)
		if toolsChanged {
			changed = true
		}
	}
	if !v1 && protocol == wire.Chat && ensureV2CompletionLimit(payload) {
		changed = true
	}
	if !changed {
		return body, renames
	}
	encoded, err := encodeAnonymousBody(payload, protocol, v1)
	if err != nil {
		// The renames are dropped with the failed re-encode: the body never
		// left the gateway, so there is nothing downstream to restore.
		return body, nil
	}
	return encoded, renames
}

// v2CompletionLimit is the max_completion_tokens a 2.x client puts on every
// chat body, so the free tier always sees the same ceiling.
const v2CompletionLimit = 32000

// ensureV2CompletionLimit adds the client's own max_completion_tokens when the
// caller did not ask for a ceiling. A caller-supplied max_tokens or
// max_completion_tokens wins, so an explicit limit is still honoured. It
// reports whether the payload changed.
func ensureV2CompletionLimit(payload map[string]any) bool {
	if _, ok := payload["max_completion_tokens"]; ok {
		return false
	}
	if _, ok := payload["max_tokens"]; ok {
		return false
	}
	payload["max_completion_tokens"] = v2CompletionLimit
	return true
}

// v2ChatKeyOrder is the order the 2.x client's JSON.stringify emits the keys of
// a chat body in. Go serialises a map alphabetically, which puts
// max_completion_tokens first where a real client starts with model; the bytes
// parse the same either way, but the gateway exists to be indistinguishable, so
// the skeleton is written in the client's order.
var v2ChatKeyOrder = []string{"model", "messages", "tools", "stream", "stream_options", "max_completion_tokens"}

// marshalV2ChatBody encodes a chat payload with v2ChatKeyOrder first and any
// remaining keys sorted after it. Values still go through encoding/json, so
// only the key order differs from a plain marshal.
func marshalV2ChatBody(payload map[string]any) ([]byte, error) {
	var buffer bytes.Buffer
	buffer.WriteByte('{')
	written := make(map[string]bool, len(payload))
	first := true
	write := func(key string) error {
		value, ok := payload[key]
		if !ok {
			return nil
		}
		keyJSON, err := jsonutil.Marshal(key)
		if err != nil {
			return err
		}
		valueJSON, err := jsonutil.Marshal(value)
		if err != nil {
			return err
		}
		if !first {
			buffer.WriteByte(',')
		}
		first = false
		buffer.Write(keyJSON)
		buffer.WriteByte(':')
		buffer.Write(valueJSON)
		written[key] = true
		return nil
	}
	for _, key := range v2ChatKeyOrder {
		if err := write(key); err != nil {
			return nil, err
		}
	}
	rest := make([]string, 0, len(payload))
	for key := range payload {
		if !written[key] {
			rest = append(rest, key)
		}
	}
	sort.Strings(rest)
	for _, key := range rest {
		if err := write(key); err != nil {
			return nil, err
		}
	}
	buffer.WriteByte('}')
	return buffer.Bytes(), nil
}

// encodeAnonymousBody renders a shaped anonymous payload in the byte layout the
// lane's client produces: 2.x chat bodies keep the client's key order, every
// other lane keeps plain encoding/json.
func encodeAnonymousBody(payload map[string]any, protocol wire.Protocol, v1 bool) ([]byte, error) {
	if !v1 && protocol == wire.Chat {
		return marshalV2ChatBody(payload)
	}
	return jsonutil.Marshal(payload)
}

// ensureAnonymousChatUsage keeps token usage available when a non-streaming
// request is forced onto the Chat SSE path. OpenAI-compatible Chat streams
// require stream_options.include_usage for the final usage event. It reports
// whether the payload changed.
func ensureAnonymousChatUsage(payload map[string]any, protocol wire.Protocol) bool {
	if protocol != wire.Chat {
		return false
	}
	options, ok := payload["stream_options"].(map[string]any)
	if !ok {
		payload["stream_options"] = map[string]any{"include_usage": true}
		return true
	}
	includeUsage, ok := options["include_usage"].(bool)
	if ok && includeUsage {
		return false
	}
	options["include_usage"] = true
	return true
}

// requestBodyDumpLimit caps how much of an outbound body is written to the log.
const requestBodyDumpLimit = 64 << 10

// dumpOutboundBodies records the exact bytes about to be sent upstream when
// logging.dump_request_bodies is enabled. It exists so retry and translation
// problems (stale rs_* references, re-encoded history, tier re-encoding) can be
// diagnosed without patching the binary. Credentials travel in headers and never
// in the body. The logger redacts configured secrets, but conversation content
// can still be sensitive. Reference IDs are retained for replay diagnostics.
func (g *Gateway) dumpOutboundBodies(route models.Route, bodies map[config.Tier][]byte, ids identity.RequestIDs, attemptOffset int) {
	if !g.cfg.Logging.DumpRequestBodies || len(bodies) == 0 {
		return
	}
	phase := "initial"
	if attemptOffset > 0 {
		phase = "retry"
	}
	tiers := make([]string, 0, len(bodies))
	for tier := range bodies {
		tiers = append(tiers, string(tier))
	}
	sort.Strings(tiers)
	for _, name := range tiers {
		tier := config.Tier(name)
		body := bodies[tier]
		if len(body) == 0 {
			continue
		}
		sum := sha256.Sum256(body)
		truncated := len(body) > requestBodyDumpLimit
		payload := body
		if truncated {
			payload = body[:requestBodyDumpLimit]
		}
		g.logger.Debug("outbound upstream request body", "component", "upstream", "event", "upstream_request_body",
			"request_id", ids.Request, "model", route.ID, "tier", tier, "protocol", route.ProtocolFor(tier),
			"phase", phase, "bytes", len(body), "sha256", hex.EncodeToString(sum[:8]),
			"truncated", truncated, "body", string(payload))
	}
}

// shapeKeyBody normalizes key-tier free-model wire bodies to agent shape
// (stream + official prompt + renamed and completed tools), mirroring the
// anonymous lane; the tier's base URL decides between v1 and v2 shaping.
// Upstream now rejects non-agent-shaped free-tier requests on every lane with
// 403 FreeTierError; paid models keep their original bodies. It reports the
// shaped body, the tool renames to restore in the response, and whether the
// body changed so the gateway can collapse the SSE stream a non-streaming
// client receives back.
func (g *Gateway) shapeKeyBody(ctx context.Context, body []byte, route models.Route, tier config.Tier) ([]byte, *wire.ToolRenames, bool) {
	if !g.catalog.IsFreeModel(route.ID) {
		return body, nil, false
	}
	baseURL := g.cfg.Upstream.Zen
	if tier == config.TierGo {
		baseURL = g.cfg.Upstream.Go
	}
	shaped, renames := prepareAnonymousBody(body, route.ProtocolFor(tier), models.IsV1Upstream(baseURL), g.requestEnvironment(ctx))
	return shaped, renames, !bytes.Equal(shaped, body)
}

// doSelectedKeyUpstream sends exactly one attempt through the operator-selected
// key. It performs no failover at all — no anonymous lane, no other key and no
// other tier — so the outcome describes that one key. It also leaves pool state
// untouched on purpose: a diagnostic request must never cool a production key or
// evict a proxy, which is exactly what made a bad Playground request degrade
// live traffic before. The attempt is still recorded in telemetry, and any HTTP
// response, whatever its status, is returned as is.
func (g *Gateway) doSelectedKeyUpstream(ctx context.Context, route models.Route, bodies map[config.Tier][]byte, ids identity.RequestIDs, override DebugKeyOverride, attemptOffset int) (*http.Response, error, int) {
	if connection := g.tierOAuth(override.Tier); connection != nil {
		if override.KeyID != oauthAccountID(connection) {
			return nil, errors.New("the selected Console plan is no longer connected"), 0
		}
		return g.doOAuthUpstream(ctx, route, bodies, ids, attemptOffset)
	}
	nodes := g.zenNodes
	baseURL := g.cfg.Upstream.Zen
	if override.Tier == config.TierGo {
		nodes = g.goNodes
		baseURL = g.cfg.Upstream.Go
	}
	node := nodes.NodeByID(override.KeyID)
	if node == nil {
		return nil, fmt.Errorf("selected %s key is no longer configured", override.Tier), 0
	}
	body := bodies[override.Tier]
	if len(body) == 0 {
		return nil, fmt.Errorf("no prepared %s request body", override.Tier), 0
	}
	shaped, toolRenames, changed := g.shapeKeyBody(ctx, body, route, override.Tier)
	if changed {
		body = shaped
	}
	setRequestShape(ctx, changed, toolRenames)
	useWARP := !node.bound && g.usesWARP(route.ID, override.Tier, false)
	proxy := nodes.Proxy(node)
	if pinned, ok := g.relayPin(ctx, proxy); ok {
		proxy, useWARP = pinned, false
	}
	if !useWARP {
		if proxy == nil {
			return nil, errors.New("selected upstream key has no proxy binding"), 0
		}
	}
	if meta := telemetry.MetaFromContext(ctx); meta != nil {
		meta.Attempts = attemptOffset + 1
		meta.Tier = string(override.Tier)
	}
	keyID := config.KeyDisplayID(node.key)
	if useWARP {
		setRequestCredential(ctx, override.Tier, keyID, "key", false, nil)
	} else {
		setRequestCredential(ctx, override.Tier, keyID, "key", false, proxy)
	}
	req, err := upstreamRequest(ctx, baseURL, route.ProtocolFor(override.Tier), body, ids, node.key)
	if err != nil {
		return nil, err, 0
	}
	if !useWARP && proxy.pool {
		req.Close = true
	}
	started := time.Now()
	var resp *http.Response
	var egress string
	if useWARP {
		resp, egress, err = g.doWARPAttempt(ctx, req, baseURL, route.ID, time.Duration(g.cfg.Performance.FirstEventTimeoutSeconds)*time.Second)
	} else {
		resp, err = doInferenceAttempt(g.inferenceClient(proxy, baseURL, route.ID), req, time.Duration(g.cfg.Performance.FirstEventTimeoutSeconds)*time.Second, g.attemptTimeout)
	}
	duration := time.Since(started)
	recordProxy := proxy
	if useWARP {
		recordProxy = warpProxy(egress)
	}
	g.recordUpstreamAttempt(ctx, route, ids, attemptOffset+1, keyID, "key", false, recordProxy, resp, err, duration)
	if err != nil {
		if useWARP {
			return nil, err, 1
		}
		return nil, asProxyUnavailable(proxy, err), 1
	}
	return resp, nil, 1
}

// doKeyUpstream rotates through the keys of route.Tier, starting from the
// session's affinity key, for at most Retry.MaxAttempts attempts; free-model
// bodies are shaped first (see shapeKeyBody). Every attempt is fed to
// observeKeyResult, which may cool the key or evict its proxy on failure. A
// 2xx ends the loop, and so does a non-retryable 4xx (see
// isNonRetryableClientResponse), which is returned as is so the caller can
// move on to the next tier; after any other response or transport error the
// next key is tried. An attempt that finishes after ctx is done ends the loop
// without being held against the key or the proxy. It returns the last
// response (body still open), else the last error, plus the number of
// attempts made.
func (g *Gateway) doKeyUpstream(ctx context.Context, route models.Route, bodies map[config.Tier][]byte, ids identity.RequestIDs, attemptOffset int) (response *http.Response, resultErr error, resultAttempts int) {
	if g.tierOAuth(route.Tier) != nil {
		return g.doOAuthUpstream(ctx, route, bodies, ids, attemptOffset)
	}
	var lastResponse *http.Response
	defer func() {
		if lastResponse != nil && lastResponse != response {
			httpx.DrainAndClose(lastResponse.Body)
		}
	}()
	var lastErr error
	nodes := g.zenNodes
	baseURL := g.cfg.Upstream.Zen
	if route.Tier == config.TierGo {
		nodes = g.goNodes
		baseURL = g.cfg.Upstream.Go
	}
	cursor := nodes.CursorFor(ids.Session)
	if nodes.Len() == 0 {
		return nil, fmt.Errorf("no %s nodes configured", route.Tier), 0
	}
	attempts := 0
	body := bodies[route.Tier]
	if len(body) == 0 {
		return nil, fmt.Errorf("no prepared %s request body", route.Tier), 0
	}
	shaped, toolRenames, changed := g.shapeKeyBody(ctx, body, route, route.Tier)
	if changed {
		body = shaped
	}
	setRequestShape(ctx, changed, toolRenames)
	useWARP := g.usesWARP(route.ID, route.Tier, false)
	// A relay-pinned diagnostic gets exactly one attempt: rotating keys would
	// no longer describe the relay that was asked for.
	attemptLimit := g.cfg.Retry.MaxAttempts
	if _, pinned := relayOverrideFrom(ctx); pinned {
		attemptLimit = 1
	}
	for attempts < attemptLimit {
		if ctx.Err() != nil {
			// Same guard as the anonymous loop: an exhausted request budget
			// must not be spent rotating keys that were never really tried.
			if lastErr == nil {
				lastErr = ctx.Err()
			}
			break
		}
		node := cursor.Next()
		if node == nil {
			break
		}
		attemptUseWARP := !node.bound && useWARP
		attempts++
		// Keep the request-level trace synchronized with the attempt that is
		// about to be sent. Only the redacted key suffix is retained.
		if meta := telemetry.MetaFromContext(ctx); meta != nil {
			meta.Attempts = attemptOffset + attempts
			meta.Tier = string(route.Tier)
		}
		bufferRetryResponse(lastResponse)
		req, err := upstreamRequest(ctx, baseURL, route.Protocol, body, ids, node.key)
		if err != nil {
			return nil, err, attempts
		}
		proxy := nodes.Proxy(node)
		// A relay pin replaces the proxy the key is bound to, so a pinned
		// diagnostic measures that relay alone.
		if pinned, ok := g.relayPin(ctx, proxy); ok {
			proxy, attemptUseWARP = pinned, false
		}
		if !attemptUseWARP {
			if proxy == nil {
				lastErr = errors.New("upstream key has no proxy binding")
				break
			}
			if proxy.pool {
				req.Close = true
			}
		}
		keyID := config.KeyDisplayID(node.key)
		if attemptUseWARP {
			setRequestCredential(ctx, route.Tier, keyID, "key", false, nil)
		} else {
			setRequestCredential(ctx, route.Tier, keyID, "key", false, proxy)
		}
		attemptStarted := time.Now()
		var resp *http.Response
		var egress string
		if attemptUseWARP {
			resp, egress, err = g.doWARPAttempt(ctx, req, baseURL, route.ID, time.Duration(g.cfg.Performance.FirstEventTimeoutSeconds)*time.Second)
		} else {
			resp, err = doInferenceAttempt(g.inferenceClient(proxy, baseURL, route.ID), req, time.Duration(g.cfg.Performance.FirstEventTimeoutSeconds)*time.Second, g.attemptTimeout)
		}
		attemptDuration := time.Since(attemptStarted)
		lastResponse = replaceRetryResponse(lastResponse, resp)
		if ctx.Err() != nil {
			// The request budget expired while this attempt was in flight. A
			// canceled context says nothing about the key or the proxy: without
			// this guard the instant DeadlineExceeded would cool a healthy key
			// and evict a healthy proxy from the pool.
			lastErr = err
			if lastErr == nil && lastResponse == nil {
				lastErr = ctx.Err()
			}
			break
		}
		recordProxy := proxy
		proxyLabel := ""
		if attemptUseWARP {
			recordProxy = warpProxy(egress)
			proxyLabel = egress
			g.observeKeyResultWARP(ctx, nodes, node, resp, err)
		} else {
			proxyLabel = config.RedactURL(proxy.name)
			g.observeKeyResult(ctx, nodes, node, proxy, resp, err)
		}
		g.recordUpstreamAttempt(ctx, route, ids, attemptOffset+attempts, keyID, "key", false, recordProxy, resp, err, attemptDuration)
		if err == nil && resp.StatusCode/100 == 2 {
			g.logger.Debug("upstream accepted request", "component", "upstream", "event", "attempt_succeeded", "request_id", ids.Request, "attempt", attempts, "tier", route.Tier, "key_id", keyID, "proxy", proxyLabel, "status", resp.StatusCode, "duration_ms", attemptDuration.Milliseconds())
			return resp, nil, attempts
		}
		// Request-shape errors are deterministic and must leave this tier without
		// rotating through unrelated keys. The outer route may still try the next
		// tier in prefer order. Authentication, throttling, server, and transport
		// failures remain retryable inside this tier.
		if isNonRetryableClientResponse(resp, err) {
			g.logger.Debug("upstream rejected a non-retryable request", "component", "upstream", "event", "attempt_rejected", "request_id", ids.Request, "attempt", attempts, "tier", route.Tier, "key_id", keyID, "status", resp.StatusCode, "proxy", proxyLabel, "duration_ms", attemptDuration.Milliseconds())
			return resp, nil, attempts
		}
		if useWARP && errors.Is(err, errWARPUnavailable) {
			// No exit at all: another key would only wait on the same pool.
			lastErr = err
			break
		}
		if useWARP {
			lastErr = err
		} else {
			lastErr = asProxyUnavailable(proxy, err)
		}
		if err != nil {
			g.logger.Debug("upstream transport attempt failed", "component", "upstream", "event", "attempt_transport_failed", "request_id", ids.Request, "attempt", attempts, "tier", route.Tier, "key_id", keyID, "proxy", proxyLabel, "duration_ms", attemptDuration.Milliseconds(), "error", err)
		} else {
			g.logger.Debug("upstream returned a retryable response", "component", "upstream", "event", "attempt_retryable_response", "request_id", ids.Request, "attempt", attempts, "tier", route.Tier, "key_id", keyID, "status", resp.StatusCode, "proxy", proxyLabel, "duration_ms", attemptDuration.Milliseconds())
		}
	}
	if errors.Is(ctx.Err(), context.Canceled) {
		return nil, ctx.Err(), attempts
	}
	if lastResponse != nil {
		return lastResponse, nil, attempts
	}
	return nil, lastErr, attempts
}

// observeKeyResult feeds the outcome of one key attempt back into proxy health
// (syncProxyResult) and the key's cooldown. Diagnostics use the same routing
// and transports as production, but must not update cooldowns, health, or
// bindings, including after successful attempts. A 2xx or non-retryable 4xx
// clears the key's cooldown. Other outcomes go to MarkFailure, which cools the
// key, unless the proxy route itself failed and the key has already been
// rebound to another proxy.
func (g *Gateway) observeKeyResult(ctx context.Context, nodes *upstreamNodes, node *upstreamNode, proxy *proxyTransport, resp *http.Response, err error) {
	if isDiagnosticRequest(ctx) {
		return
	}
	status := upstreamStatus(resp)
	proxyFailed := g.syncProxyResult(ctx, proxy, status, err)
	if err == nil && status/100 == 2 || isNonRetryableClientResponse(resp, err) {
		nodes.MarkSuccess(node)
		return
	}
	if !proxyFailed || nodes.Proxy(node) == proxy {
		nodes.MarkFailure(node, resp, err)
	}
}

// observeAnonymousResult is the anonymous counterpart of observeKeyResult: it
// syncs the proxy's health and clears or extends the anonymous node's
// per-proxy cooldown, except for diagnostic requests.
func (g *Gateway) observeAnonymousResult(ctx context.Context, node *anonymousNode, resp *http.Response, err error) {
	if isDiagnosticRequest(ctx) {
		return
	}
	status := upstreamStatus(resp)
	g.syncProxyResult(ctx, node.proxy, status, err)
	if err == nil && status/100 == 2 {
		g.anonymous.MarkSuccess(node)
		g.anonymous.NoteSuccess()
	} else {
		g.anonymous.MarkFailure(node, resp, err)
		if resp != nil && peekNetworkAbuseBlock(resp) {
			// An IP block is scoped to this exit; doAnonymousUpstream marks it
			// blocked and opens the lane breaker only when no exit is left.
			// Counting it here as well would stop the other exits early.
			return
		}
		if pause, tripped := g.anonymous.NoteFailure(); tripped {
			g.logger.Warn("anonymous lane circuit breaker opened",
				"component", "upstream", "event", "anonymous_breaker_open", "status", status, "paused_for", pause.String())
		}
	}
}

func upstreamStatus(resp *http.Response) int {
	if resp == nil {
		return 0
	}
	return resp.StatusCode
}

// setRequestCredential records the credential and proxy of the attempt about
// to be sent on the request's telemetry meta, with the proxy URL redacted. It
// is a no-op when ctx carries no meta.
func setRequestCredential(ctx context.Context, tier config.Tier, keyID, channel string, anonymous bool, proxy *proxyTransport) {
	meta := telemetry.MetaFromContext(ctx)
	if meta == nil {
		return
	}
	meta.Tier = string(tier)
	meta.KeyID = keyID
	meta.Channel = channel
	meta.Anonymous = anonymous
	meta.Proxy = ""
	if proxy != nil {
		meta.Proxy = config.RedactURL(proxy.name)
	}
}

func requestCredential(ctx context.Context) (string, string, bool) {
	meta := telemetry.MetaFromContext(ctx)
	if meta == nil {
		return "", "", false
	}
	return meta.KeyID, meta.Channel, meta.Anonymous
}

// recordUpstreamAttempt classifies one finished attempt (success, rejected,
// retryable_failure or transport_error), appends its leg to the request's
// telemetry meta and reports it to the metrics monitor when one is configured.
func (g *Gateway) recordUpstreamAttempt(ctx context.Context, route models.Route, ids identity.RequestIDs, attempt int, keyID, channel string, anonymous bool, proxy *proxyTransport, resp *http.Response, err error, duration time.Duration) {
	status := upstreamStatus(resp)
	success := err == nil && status >= 200 && status < 300
	outcome := "retryable_failure"
	if success {
		outcome = "success"
	} else if err != nil {
		outcome = "transport_error"
	} else if isNonRetryableClientResponse(resp, nil) {
		outcome = "rejected"
	}
	if meta := telemetry.MetaFromContext(ctx); meta != nil {
		meta.AttemptOutcome = outcome
		meta.Protocol = route.Protocol
		// Append a per-attempt leg (key:status:ms, with "anon" as the key
		// on the anonymous lane) so the request log shows the whole attempt
		// chain at a glance. Only the redacted key suffix is retained.
		label := keyID
		if anonymous {
			label = "anon"
		}
		leg := label + ":"
		if err != nil {
			leg += classifyAttemptError(err)
		} else {
			leg += strconv.Itoa(status)
		}
		leg += ":" + strconv.FormatInt(max(duration.Milliseconds(), 0), 10) + "ms"
		if anonymous && proxy != nil {
			leg += "@" + config.RedactURL(proxy.name)
		}
		meta.Legs = append(meta.Legs, leg)
	}
	if g.monitor == nil {
		return
	}
	proxyName := "unavailable"
	if proxy != nil {
		proxyName = config.RedactURL(proxy.name)
	}
	g.monitor.RecordAttempt(telemetry.UpstreamAttempt{
		Time: time.Now().UTC(), RequestID: ids.Request, Model: route.ID, Tier: string(route.Tier), Attempt: attempt,
		KeyID: keyID, Channel: channel, Anonymous: anonymous, Proxy: proxyName, Status: status,
		DurationMS: max(duration.Milliseconds(), 0), Success: success, Outcome: outcome,
	})
	if channel != "oauth" && !isDiagnosticRequest(ctx) && g.availability != nil && g.catalog.IsFreeModel(route.ID) {
		bodySnippet := ""
		if resp != nil && (resp.StatusCode == 400 || resp.StatusCode == 404 || resp.StatusCode == 410 || resp.StatusCode == 422) {
			bodySnippet = string(peekResponseBody(resp))
		}
		_ = g.availability.RecordPassiveObservation(route.ID, success, status, bodySnippet, channel, time.Now().UTC())
	}
}

// upstreamRequest builds the POST for one attempt: baseURL plus the protocol's
// /v1/... route, carrying body. The header set follows the lane: setV1Headers
// when models.IsV1Upstream(baseURL), setV2Headers otherwise. Anthropic
// endpoints on a v2 lane gain beta=true, matching the 2.x client; the 1.x lane
// keeps its shape. key is sent as x-api-key (with anthropic-version) on the
// Anthropic protocol and as a Bearer token on every other one; the anonymous
// lane passes anonymousZenKey.
func upstreamRequest(ctx context.Context, baseURL string, protocol wire.Protocol, body []byte, ids identity.RequestIDs, key string) (*http.Request, error) {
	endpoint := strings.TrimRight(baseURL, "/") + wire.Path(protocol)
	if !models.IsV1Upstream(baseURL) {
		endpoint = strings.TrimRight(baseURL, "/") + v2EndpointPath(baseURL, protocol)
	}
	if protocol == wire.Anthropic && !models.IsV1Upstream(baseURL) {
		endpoint = withAnthropicBeta(endpoint)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")
	if models.IsV1Upstream(baseURL) {
		setV1Headers(req.Header, protocol, body, ids)
	} else {
		setV2Headers(req.Header, protocol, ids)
	}
	if protocol == wire.Anthropic {
		req.Header.Set("x-api-key", key)
		req.Header.Set("anthropic-version", "2023-06-01")
	} else {
		// The anonymous credential is the literal token "public". The 2026-10-14
		// gate rejects keyless requests (an absent header used to pass) and is
		// case-sensitive: "Bearer PUBLIC" 401s.
		req.Header.Set("Authorization", "Bearer "+key)
	}
	return req, nil
}

// v2EndpointPath returns the route a 2.1 client posts to on a v2 origin. The
// 2.1 client groups /inference routes by provider family, so the family
// segment sits between the origin and the protocol path (a 2.0.32 client
// posted the protocol path directly, and that route still answers). Origins
// that are not the /inference gateway — a custom base, or /zen/go — keep the
// flat route, because the family grouping is specific to /inference.
func v2EndpointPath(baseURL string, protocol wire.Protocol) string {
	parsed, err := url.Parse(baseURL)
	if err != nil || !strings.HasSuffix(strings.TrimRight(parsed.Path, "/"), "/inference") {
		return wire.Path(protocol)
	}
	family := "openai"
	if protocol == wire.Anthropic {
		family = "anthropic"
	}
	return "/" + family + wire.Path(protocol)
}

// withAnthropicBeta marks an Anthropic endpoint as beta the way the OpenCode
// 2.x client does, preserving any query a configured base URL already carries.
func withAnthropicBeta(endpoint string) string {
	parsed, err := url.Parse(endpoint)
	if err != nil {
		return endpoint
	}
	query := parsed.Query()
	if query.Get("beta") == "true" {
		return endpoint
	}
	query.Set("beta", "true")
	parsed.RawQuery = query.Encode()
	return parsed.String()
}

// setV1Headers renders the v1 lane's header set, that of an OpenCode 1.19.3
// model request on its opencode provider, as captured from the official
// release: the AI SDK User-Agent of the package serving the protocol, both
// session headers, the user message id as x-opencode-request (a fresh
// ascending msg_ id when none was derived), the git root commit as the
// project, the canonical parent session under both parent headers, and only
// the anthropic-beta flags the AI SDK derives from the body. The v1 client
// sends no x-session-affinity or X-Session-Id to this provider.
func setV1Headers(header http.Header, protocol wire.Protocol, body []byte, ids identity.RequestIDs) {
	header.Set("Accept", "*/*")
	header.Set("User-Agent", httpx.V1ModelUserAgent(v1ProviderUtils(protocol)))
	header.Set("x-opencode-client", "cli")
	header.Set("x-opencode-session", ids.Session)
	header.Set("x-opencode-session-id", ids.Session)
	message := ids.Message
	if message == "" {
		message = identity.AscendingID("msg", time.Now())
	}
	header.Set("x-opencode-request", message)
	header.Set("x-opencode-project", projectID(ids.Project))
	if ids.ParentSession != "" {
		parent := identity.CanonicalSessionID(ids.ParentSession)
		header.Set("x-opencode-parent-session-id", parent)
		header.Set("x-parent-session-id", parent)
	}
	if protocol == wire.Anthropic {
		if betas := v1AnthropicBetas(body); betas != "" {
			header.Set("anthropic-beta", betas)
		}
	}
}

// setV2Headers renders the OpenCode 2.x CLI header set the v2 gates
// fingerprint: the "opencode/<channel>/<version>/cli" User-Agent, the
// client's child session as x-opencode-session-id, the conversation affinity
// (the canonical parent when one is present) as x-opencode-session,
// x-session-affinity and X-Session-Id, and a bare 40-character hex
// x-opencode-project. The v2 gate rejects x-opencode-request and canonical
// prj_* project ids with 403 FreeTierError, so neither is sent. Anthropic
// requests carry a fixed anthropic-beta set; upstreamRequest adds
// anthropic-version and the beta query.
func setV2Headers(header http.Header, protocol wire.Protocol, ids identity.RequestIDs) {
	header.Set("x-opencode-client", "cli")
	rootSession := ids.Session
	if ids.ParentSession != "" {
		parent := identity.CanonicalSessionID(ids.ParentSession)
		rootSession = parent
		header.Set("x-opencode-parent-session-id", parent)
		header.Set("x-parent-session-id", parent)
	}
	childSession := ids.ChildSession
	if childSession == "" {
		childSession = ids.Session
	}
	header.Set("x-session-affinity", rootSession)
	header.Set("X-Session-Id", rootSession)
	header.Set("x-opencode-session", rootSession)
	header.Set("x-opencode-session-id", childSession)
	header.Set("User-Agent", httpx.V2UserAgent())
	header.Set("x-opencode-project", projectID(ids.Project))
	if protocol == wire.Anthropic {
		header.Set("anthropic-beta", "interleaved-thinking-2025-05-14")
	}
}

// v1ProviderUtils names the provider-utils version of the AI SDK package the
// OpenCode 1.x client routes a protocol through, for the v1 User-Agent. System
// One has no v1 counterpart and reports the chat package.
func v1ProviderUtils(protocol wire.Protocol) string {
	switch protocol {
	case wire.Responses:
		return httpx.V1ResponsesSDK
	case wire.Anthropic:
		return httpx.V1AnthropicSDK
	default:
		return httpx.V1ChatSDK
	}
}

// gitCommitPattern matches the git root commit hash OpenCode uses as its
// project id on both lanes.
var gitCommitPattern = regexp.MustCompile(`^[0-9a-f]{40}$`)

// v1AnthropicBetaRequest holds the Messages body fields the AI SDK
// anthropic provider derives beta flags from. Fields whose JSON type varies
// stay raw so one unexpected value cannot hide the others.
type v1AnthropicBetaRequest struct {
	Model             string            `json:"model"`
	MCPServers        []json.RawMessage `json:"mcp_servers"`
	ContextManagement *struct {
		Edits []struct {
			Type string `json:"type"`
		} `json:"edits"`
	} `json:"context_management"`
	Container    json.RawMessage `json:"container"`
	OutputConfig struct {
		TaskBudget json.RawMessage `json:"task_budget"`
	} `json:"output_config"`
	Speed     json.RawMessage `json:"speed"`
	Fallbacks json.RawMessage `json:"fallbacks"`
	Thinking  struct {
		BlockBinding json.RawMessage `json:"block_binding"`
	} `json:"thinking"`
	Tools []struct {
		Type           string          `json:"type"`
		InputExamples  json.RawMessage `json:"input_examples"`
		AllowedCallers json.RawMessage `json:"allowed_callers"`
	} `json:"tools"`
}

// v1AnthropicToolBetas maps the server tool types of a Messages body to the
// beta flag the AI SDK anthropic provider sends with each.
var v1AnthropicToolBetas = map[string]string{
	"code_execution_20250522": "code-execution-2025-05-22",
	"code_execution_20250825": "code-execution-2025-08-25",
	"computer_20241022":       "computer-use-2024-10-22",
	"computer_20250124":       "computer-use-2025-01-24",
	"computer_20251124":       "computer-use-2025-11-24",
	"text_editor_20241022":    "computer-use-2024-10-22",
	"text_editor_20250124":    "computer-use-2025-01-24",
	"text_editor_20250429":    "computer-use-2025-01-24",
	"bash_20241022":           "computer-use-2024-10-22",
	"bash_20250124":           "computer-use-2025-01-24",
	"memory_20250818":         "context-management-2025-06-27",
	"web_fetch_20250910":      "web-fetch-2025-09-10",
	"web_fetch_20260209":      "code-execution-web-tools-2026-02-09",
	"web_search_20260209":     "code-execution-web-tools-2026-02-09",
	"advisor_20260301":        "advisor-tool-2026-03-01",
}

// v1AnthropicBetas returns the anthropic-beta value OpenCode 1.19.3 sends
// with a Messages body on the v1 lane, or "" when no flag applies. Its
// opencode provider sets no fixed betas: the AI SDK derives them from the
// request features (body features first, then tools, in the SDK's order), and
// per-tool eager_input_streaming has replaced the old
// fine-grained-tool-streaming flag.
func v1AnthropicBetas(body []byte) string {
	var request v1AnthropicBetaRequest
	// A field of an unexpected type fails alone; the rest still decode.
	_ = json.Unmarshal(body, &request)
	var betas []string
	add := func(beta string) {
		if !slices.Contains(betas, beta) {
			betas = append(betas, beta)
		}
	}
	if len(request.MCPServers) > 0 {
		add("mcp-client-2025-04-04")
	}
	if request.ContextManagement != nil {
		add("context-management-2025-06-27")
		for _, edit := range request.ContextManagement.Edits {
			if edit.Type == "compact_20260112" {
				add("compact-2026-01-12")
			}
		}
	}
	var container struct {
		Skills []json.RawMessage `json:"skills"`
	}
	if json.Unmarshal(request.Container, &container) == nil && len(container.Skills) > 0 {
		add("code-execution-2025-08-25")
		add("skills-2025-10-02")
		add("files-api-2025-04-14")
	}
	if isPresentJSON(request.OutputConfig.TaskBudget) {
		add("task-budgets-2026-03-13")
	}
	if string(request.Speed) == `"fast"` {
		add("fast-mode-2026-02-01")
	}
	var fallbacks []json.RawMessage
	if string(request.Fallbacks) == `"default"` {
		add("server-side-fallback-2026-07-01")
	} else if json.Unmarshal(request.Fallbacks, &fallbacks) == nil && len(fallbacks) > 0 {
		add("server-side-fallback-2026-06-01")
	}
	if isPresentJSON(request.Thinking.BlockBinding) {
		add("thinking-binding-controls-2026-08-01")
	}
	for _, tool := range request.Tools {
		if tool.Type == "" || tool.Type == "custom" {
			if anthropicSupportsStructuredOutput(request.Model) {
				add("structured-outputs-2025-11-13")
			}
			if isPresentJSON(tool.InputExamples) || isPresentJSON(tool.AllowedCallers) {
				add("advanced-tool-use-2025-11-20")
			}
		} else if beta := v1AnthropicToolBetas[tool.Type]; beta != "" {
			add(beta)
		}
	}
	return strings.Join(betas, ",")
}

func isPresentJSON(raw json.RawMessage) bool {
	return len(raw) > 0 && string(raw) != "null"
}

// claude3OrOlderPattern matches the Claude model families older than Claude 4
// (Claude Instant, Claude 2 and every Claude 3.x model) that the AI SDK treats
// as lacking structured output.
var claude3OrOlderPattern = regexp.MustCompile(`claude-(?:instant(?:-|$)|v?2(?:$|[-.:])|3(?:$|[-.]))`)

// anthropicSupportsStructuredOutput mirrors the AI SDK anthropic provider's
// model capability table, checked in the same order: the dated Claude 4.0
// releases and Claude 3 and older lack structured output, every other Claude
// model has it, and non-Claude models do not.
func anthropicSupportsStructuredOutput(model string) bool {
	for _, supported := range []string{
		"claude-opus-5", "claude-opus-4-8", "claude-opus-4-7", "claude-fable-5", "claude-sonnet-5",
		"claude-sonnet-4-6", "claude-opus-4-6", "claude-sonnet-4-5", "claude-opus-4-5", "claude-haiku-4-5",
		"claude-opus-4-1",
	} {
		if strings.Contains(model, supported) {
			return true
		}
	}
	if strings.Contains(model, "claude-sonnet-4-") || strings.Contains(model, "claude-opus-4-") ||
		strings.Contains(model, "claude-3-haiku") || claude3OrOlderPattern.MatchString(model) {
		return false
	}
	return strings.Contains(model, "claude-")
}

// projectID renders the project header in the shape both lanes use: the
// genuine git root commit hash or "global" is kept verbatim, and any other
// project is hashed into the same 40-character lowercase hex shape. The value
// itself is not checked upstream, only its shape, but hashing keeps one
// project mapped to one stable upstream project id and masks a caller's
// prj_*-style project, which the v2 gate rejects.
func projectID(project string) string {
	if project == "global" || gitCommitPattern.MatchString(project) {
		return project
	}
	sum := sha256.Sum256([]byte("opencode-project\x00" + project))
	return hex.EncodeToString(sum[:20])
}

// isNonRetryableClientResponse reports whether resp is a 4xx that retrying on
// another key of the same tier cannot fix: every 4xx except 401, 403 and 429,
// which can be specific to the key. A transport error is never non-retryable.
func isNonRetryableClientResponse(resp *http.Response, err error) bool {
	return err == nil && resp != nil && resp.StatusCode >= 400 && resp.StatusCode < 500 && resp.StatusCode != http.StatusUnauthorized && resp.StatusCode != http.StatusForbidden && resp.StatusCode != http.StatusTooManyRequests
}

// relayPin returns the proxy a relay-pinned diagnostic names, and whether a
// pin applied. An unresolvable pin keeps the request on its normal proxy: the
// admin endpoint validates the selection before it reaches here.
func (g *Gateway) relayPin(ctx context.Context, current *proxyTransport) (*proxyTransport, bool) {
	selection, ok := relayOverrideFrom(ctx)
	if !ok {
		return current, false
	}
	if pinned, found := g.RelayProxy(selection); found {
		return pinned, true
	}
	return current, false
}

internal/gateway/warp.go:
package gateway

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"strings"
	"sync"
	"time"

	"opencode2api/internal/config"
	"opencode2api/internal/httpx"
	"opencode2api/internal/identity"
	"opencode2api/internal/models"
	wire "opencode2api/internal/protocol"
	"opencode2api/internal/telemetry"
	"opencode2api/internal/warp"
)

// errWARPUnavailable marks a free-lane attempt that could not acquire a WARP
// exit at all. The client gets a 503 that points at the egress switch instead
// of a generic upstream failure.
var errWARPUnavailable = errors.New("WARP egress is unavailable")

// warpUnavailableMessage is what a client receives when the free lane is
// configured to leave through WARP but no exit could be acquired. It is a 503
// because the request never reached the upstream.
const warpUnavailableMessage = "no WARP exit could carry this free-model request; the upstream was not contacted. Check the WARP switch and this host's UDP access to the Cloudflare endpoint."

// usesWARP reports whether this request's egress must bypass proxies. Only
// free models on the anonymous lane and the Zen key tier qualify; the Go plan
// and paid models keep their proxy bindings.
func (g *Gateway) usesWARP(model string, tier config.Tier, anonymous bool) bool {
	return g.warp != nil && g.catalog.IsFreeModel(model) && (anonymous || tier == config.TierZen)
}

// warpUsesBun mirrors inferenceClient for traffic that leaves through WARP:
// free-model traffic to the v1 /zen lane or the v2 /inference origin must look
// like the official Bun runtime. The other lanes use the regular client.
func (g *Gateway) warpUsesBun(baseURL, model string) bool {
	lane := strings.ToLower(strings.TrimRight(strings.TrimSpace(baseURL), "/"))
	return g.catalog.IsFreeModel(model) && (models.IsV1Upstream(baseURL) || strings.HasSuffix(lane, "/inference"))
}

// warpLease is one acquired WARP exit together with the HTTP clients that dial
// through it. Every client is per-attempt: the exit is released as soon as the
// response body is closed, so pooled connections must be closed at the same
// time.
type warpLease struct {
	lease   *warp.Lease
	pool    *warp.Pool
	regular *http.Client
	bun     *http.Client
	useBun  bool
	once    sync.Once
}

func (g *Gateway) newWarpLease(lease *warp.Lease, useBun bool) (*warpLease, error) {
	perf := g.cfg.Performance
	dial := func(ctx context.Context, _, address string) (net.Conn, error) {
		return lease.DialContext(ctx, lease.DialNetwork(), address)
	}
	transport := http.DefaultTransport.(*http.Transport).Clone()
	transport.Proxy = nil
	transport.DialContext = dial
	transport.ForceAttemptHTTP2 = false
	// A clone of DefaultTransport made after its first dial inherits the
	// configured HTTP/2 ALPN and TLSNextProto map, so the transport negotiates
	// h2 and then hands SETTINGS frames to the HTTP/1.x reader ("malformed HTTP
	// response"). Every WARP attempt must speak HTTP/1.1 over a fresh tunnel,
	// so pin the ALPN and disable the h2 wiring explicitly.
	transport.TLSNextProto = make(map[string]func(authority string, c *tls.Conn) http.RoundTripper)
	if transport.TLSClientConfig == nil {
		transport.TLSClientConfig = &tls.Config{NextProtos: []string{"http/1.1"}}
	} else {
		tlsCfg := transport.TLSClientConfig.Clone()
		tlsCfg.NextProtos = []string{"http/1.1"}
		transport.TLSClientConfig = tlsCfg
	}
	transport.MaxIdleConns = perf.MaxIdleConns
	transport.MaxIdleConnsPerHost = perf.MaxIdleConnsPerHost
	transport.MaxConnsPerHost = perf.MaxConnsPerHost
	transport.IdleConnTimeout = time.Duration(perf.IdleConnTimeoutSeconds) * time.Second
	transport.ResponseHeaderTimeout = g.attemptTimeout
	bun, err := httpx.NewBunTransport(httpx.BunOptions{
		DialContext:           dial,
		ConnectTimeout:        time.Duration(perf.ConnectTimeoutSeconds) * time.Second,
		ResponseHeaderTimeout: g.attemptTimeout,
		IdleConnTimeout:       transport.IdleConnTimeout,
		MaxIdleConnsPerHost:   perf.MaxIdleConnsPerHost,
	})
	if err != nil {
		return nil, err
	}
	rejectRedirect := func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	return &warpLease{
		lease:   lease,
		pool:    g.warp,
		regular: &http.Client{Transport: transport, CheckRedirect: rejectRedirect},
		bun:     &http.Client{Transport: bun, CheckRedirect: rejectRedirect},
		useBun:  useBun,
	}, nil
}

func (l *warpLease) client() *http.Client {
	if l.useBun {
		return l.bun
	}
	return l.regular
}

func (l *warpLease) close() {
	if l == nil {
		return
	}
	l.once.Do(func() {
		l.bun.CloseIdleConnections()
		l.regular.CloseIdleConnections()
		l.lease.Release()
	})
}

// warpBody ties the lease to the response body. Closing the body (or the
// gateway's drain helpers) releases the exit, and an upstream stream that dies
// mid-body retires the exit that carried it.
type warpBody struct {
	io.ReadCloser
	lease      *warpLease
	diagnostic bool
}

func (b *warpBody) Read(data []byte) (int, error) {
	n, err := b.ReadCloser.Read(data)
	if err != nil && err != io.EOF && !b.diagnostic && !errors.Is(err, context.Canceled) {
		b.lease.pool.Fail(b.lease.lease, "stream read error")
	}
	return n, err
}

func (b *warpBody) Close() error {
	err := b.ReadCloser.Close()
	b.lease.close()
	return err
}

// warpFailReason names the condition that should retire an exit. A stalled
// first token is treated as a tunnel failure: retrying the same userspace
// tunnel would only repeat the stall.
func warpFailReason(err error) string {
	switch {
	case errors.Is(err, errFirstEventTimeout):
		return "first event timeout"
	case errors.Is(err, errAttemptTimeout):
		return "attempt timeout"
	default:
		return "transport error"
	}
}

// doWARPAttempt sends one prepared request through an acquired WARP exit,
// feeds the outcome back into the pool, and returns the response with a body
// that releases the exit when closed. The egress label is returned for
// telemetry ("warp:<public address>").
func (g *Gateway) doWARPAttempt(ctx context.Context, req *http.Request, baseURL, model string, firstEventTimeout time.Duration) (*http.Response, string, error) {
	lease, err := g.warp.Acquire(ctx)
	if err != nil {
		if ctx.Err() != nil {
			return nil, "", ctx.Err()
		}
		return nil, "", fmt.Errorf("%w: %v", errWARPUnavailable, err)
	}
	owned, err := g.newWarpLease(lease, g.warpUsesBun(baseURL, model))
	if err != nil {
		lease.Release()
		return nil, "", fmt.Errorf("%w: %v", errWARPUnavailable, err)
	}
	label := "warp:" + lease.EgressKey()
	setWarpEgress(ctx, label)
	diagnostic := isDiagnosticRequest(ctx)
	resp, err := doInferenceAttempt(owned.client(), req, firstEventTimeout, g.attemptTimeout)
	if err != nil {
		if ctx.Err() == nil && !diagnostic {
			g.warp.Fail(lease, warpFailReason(err))
		}
		owned.close()
		return nil, label, err
	}
	if !diagnostic {
		var body []byte
		if resp.StatusCode == http.StatusForbidden || resp.StatusCode == http.StatusTooManyRequests {
			body = peekResponseBody(resp)
		}
		var retryAfter time.Duration
		if resp.StatusCode == http.StatusTooManyRequests {
			retryAfter = parseRetryAfter(resp.Header.Get("Retry-After"))
		}
		g.warp.ReportWithRetryAfter(lease, resp.StatusCode, body, retryAfter)
	}
	resp.Body = &warpBody{ReadCloser: resp.Body, lease: owned, diagnostic: diagnostic}
	return resp, label, nil
}

// setWarpEgress records the exit that actually carries the attempt so request
// logs show the WARP address instead of the unused key proxy binding.
func setWarpEgress(ctx context.Context, label string) {
	if meta := telemetry.MetaFromContext(ctx); meta != nil {
		meta.Proxy = label
	}
}

// warpProxy is a name-only proxyTransport used by telemetry records for WARP
// attempts. The value is never used for dialing or health tracking.
func warpProxy(label string) *proxyTransport {
	if label == "" {
		return nil
	}
	return &proxyTransport{name: label}
}

// doWarpAnonymousUpstream is the anonymous lane with WARP as its only egress.
// It walks the same two upstream gates (v2 /inference first, v1 /zen second)
// as doAnonymousUpstream, but draws a WARP lease per attempt instead of a
// proxy. The lane breaker still applies; per-proxy cooldowns and the block
// cursor do not, because a block is a property of the WARP exit and rotation
// replaces it.
func (g *Gateway) doWarpAnonymousUpstream(ctx context.Context, route models.Route, bodies map[config.Tier][]byte, ids identity.RequestIDs, attemptOffset int) (response *http.Response, resultErr error, resultAttempts int) {
	if !g.anonymous.AllowAttempt() {
		return nil, errAnonymousLanePaused, 0
	}
	defer g.anonymous.ReleaseProbe()
	rawBody := bodies[config.TierZen]
	if len(rawBody) == 0 {
		return nil, errors.New("no prepared Zen request body"), 0
	}
	protocol := route.ProtocolFor(config.TierZen)
	upstreams := g.anonymousUpstreams()
	prepared := make([][]byte, len(upstreams))
	renames := make([]*wire.ToolRenames, len(upstreams))
	for index, baseURL := range upstreams {
		prepared[index], renames[index] = prepareAnonymousBody(rawBody, protocol, models.IsV1Upstream(baseURL), g.requestEnvironment(ctx))
	}
	// A 429 is scoped to the exit that carried it, so the request keeps
	// rotating exits until the configured attempt budget is spent; only then
	// does the last 429 reach the client.
	isTitle := isTitleGenerationBody(rawBody)
	limit := g.cfg.Retry.MaxAttempts
	if limit < 1 || isTitle {
		// A title request gets one attempt: on failure it is answered locally.
		limit = 1
	}
	firstEventTimeout := time.Duration(g.cfg.Performance.FirstEventTimeoutSeconds) * time.Second
	var lastResponse *http.Response
	defer func() {
		if lastResponse != nil && lastResponse != response {
			httpx.DrainAndClose(lastResponse.Body)
		}
	}()
	var lastErr error
	blocked, halted := false, false
	attempts := 0
	triedEgresses := make(map[string]bool)
	for attempts < limit {
		if ctx.Err() != nil {
			if lastErr == nil {
				lastErr = ctx.Err()
			}
			break
		}
		leaseBlocked := false
		lastStatus := 0
		for index, baseURL := range upstreams {
			if ctx.Err() != nil {
				break
			}
			setRequestShape(ctx, false, renames[index])
			attempts++
			if meta := telemetry.MetaFromContext(ctx); meta != nil {
				meta.Attempts = attemptOffset + attempts
				meta.Tier = string(config.TierZen)
			}
			bufferRetryResponse(lastResponse)
			req, err := upstreamRequest(ctx, baseURL, protocol, prepared[index], ids, anonymousZenKey)
			if err != nil {
				return nil, err, attempts
			}
			setRequestCredential(ctx, config.TierZen, "anonymous", "anonymous", true, nil)
			started := time.Now()
			resp, egress, err := g.doWARPAttempt(ctx, req, baseURL, route.ID, firstEventTimeout)
			duration := time.Since(started)
			lastResponse = replaceRetryResponse(lastResponse, resp)
			if ctx.Err() != nil {
				lastErr = err
				if lastErr == nil && lastResponse == nil {
					lastErr = ctx.Err()
				}
				break
			}
			status := upstreamStatus(resp)
			lastStatus = status
			g.recordUpstreamAttempt(ctx, route, ids, attemptOffset+attempts, "anonymous", "anonymous", true, warpProxy(egress), resp, err, duration)
			if err == nil && status/100 == 2 {
				g.anonymous.NoteSuccess()
				g.logger.Debug("anonymous WARP upstream accepted request", "component", "upstream", "event", "anonymous_attempt_succeeded", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "key_id", "anonymous", "channel", "anonymous", "anonymous", true, "proxy", egress, "status", status, "duration_ms", duration.Milliseconds())
				return resp, nil, attempts
			}
			lastErr = err
			if err != nil {
				g.logger.Debug("anonymous WARP transport attempt failed", "component", "upstream", "event", "anonymous_attempt_transport_failed", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "key_id", "anonymous", "channel", "anonymous", "anonymous", true, "proxy", egress, "duration_ms", duration.Milliseconds(), "error", err)
				// A broken tunnel affects both upstream gates; rotate the exit
				// instead of repeating the request on the same lease.
				break
			}
			if peekNetworkAbuseBlock(resp) {
				lastErr = errFreeTierIPBlocked
				blocked, leaseBlocked = true, true
				g.logger.Warn("free tier blocked the WARP exit; rotating it", "component", "upstream", "event", "free_tier_ip_blocked", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "proxy", egress)
				break
			}
			if isDeterministicClientResponse(status, peekResponseBody(resp)) {
				lastErr = errDeterministicClientRejection
				halted = true
				g.logger.Warn("upstream rejected the request; not trying other upstreams", "component", "upstream", "event", "deterministic_rejection", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "status", status, "duration_ms", duration.Milliseconds())
				break
			}
			if status == http.StatusTooManyRequests {
				triedEgresses[strings.TrimPrefix(egress, "warp:")] = true
				if !g.warp.HasUntriedActive(triedEgresses) {
					g.logger.Warn("all active WARP exits exhausted or cooling down; stopping retries", "component", "upstream", "event", "warp_429_exhausted", "request_id", ids.Request, "attempt", attempts)
					break
				}
			}
			g.logger.Debug("anonymous WARP upstream returned an error response; trying the next upstream or exit", "component", "upstream", "event", "anonymous_attempt_response_failed", "request_id", ids.Request, "attempt", attempts, "tier", config.TierZen, "upstream", config.RedactURL(baseURL), "key_id", "anonymous", "channel", "anonymous", "anonymous", true, "proxy", egress, "status", status, "duration_ms", duration.Milliseconds())
			if index+1 < len(upstreams) {
				break
			}
		}
		if halted || ctx.Err() != nil {
			break
		}
		if lastStatus == http.StatusTooManyRequests {
			if !g.warp.HasUntriedActive(triedEgresses) {
				break
			}
		}
		if !leaseBlocked && lastStatus != http.StatusTooManyRequests {
			if pause, tripped := g.anonymous.NoteFailure(); tripped {
				g.logger.Warn("anonymous lane circuit breaker opened", "component", "upstream", "event", "anonymous_breaker_open", "status", lastStatus, "paused_for", pause.String())
				break
			}
		}
	}
	if errors.Is(ctx.Err(), context.Canceled) {
		return nil, ctx.Err(), attempts
	}
	if halted {
		return lastResponse, errDeterministicClientRejection, attempts
	}
	if isTitle {
		if fallback := titleFallback(g.logger, route.ID, rawBody, lastResponse, lastErr); fallback != nil {
			lastResponse = nil
			return fallback, nil, attempts
		}
	}
	if lastResponse != nil {
		if blocked {
			return lastResponse, errFreeTierIPBlocked, attempts
		}
		return lastResponse, nil, attempts
	}
	if blocked {
		return nil, errFreeTierIPBlocked, attempts
	}
	if lastErr == nil {
		lastErr = errWARPUnavailable
	}
	return nil, lastErr, attempts
}

// observeKeyResultWARP is observeKeyResult for a keyed attempt that left
// through WARP: the key still cools on an upstream rejection, but failures of
// the tunnel itself (no exit, dial or first-event failure) are not the key's
// fault and must not cool it.
func (g *Gateway) observeKeyResultWARP(ctx context.Context, nodes *upstreamNodes, node *upstreamNode, resp *http.Response, err error) {
	if isDiagnosticRequest(ctx) {
		return
	}
	status := upstreamStatus(resp)
	if err == nil && status/100 == 2 || isNonRetryableClientResponse(resp, err) {
		nodes.MarkSuccess(node)
		return
	}
	if err != nil && resp == nil {
		// The lease acquisition, dial, or first event failed: the upstream
		// never judged this key. The pool already retired the exit.
		return
	}
	// A 429 or a network-abuse 403 is scoped to the WARP exit, which the pool
	// has just retired; holding it against the key would stop a single-key
	// rotation after the first attempt instead of retrying on a fresh exit.
	if resp != nil && (resp.StatusCode == http.StatusTooManyRequests || peekNetworkAbuseBlock(resp)) {
		return
	}
	nodes.MarkFailure(node, resp, err)
}

internal/gateway/gateway.go:
// Package gateway routes inference requests through managed upstream pools.
//
// Upstreams fall into two lanes, named after the OpenCode client generation
// whose request shape they expect, not after their URL path: both lanes
// append the /v1/... route segment. The v1 lane is the https://opencode.ai/zen
// origin (models.V1Base, also the default upstream.zen), which
// models.IsV1Upstream detects. It expects the OpenCode 1.x client shape: the
// 1.x User-Agent, the x-opencode-request header, a git-commit-shaped project
// and, on the free tier, the 1.x toolset. The v2 lane is the /inference
// origin (upstream.anonymous) and the Go plan's /zen/go origin, which expect
// the OpenCode 2.x CLI shape. The anonymous free tier uses the configured v2
// /inference origin only.
package gateway

import (
	"bytes"
	"context"
	"crypto/subtle"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"strings"
	"sync"
	"time"

	"opencode2api/internal/config"
	"opencode2api/internal/httpx"
	"opencode2api/internal/identity"
	"opencode2api/internal/jsonutil"
	"opencode2api/internal/models"
	"opencode2api/internal/oauth"
	wire "opencode2api/internal/protocol"
	"opencode2api/internal/rotation"
	"opencode2api/internal/telemetry"
	"opencode2api/internal/warp"
)

const maxRequestBody = 32 << 20

// anonymousZenKey is the shared credential the anonymous free tier sends as
// its API key.
const anonymousZenKey = "public"

// attemptDeadline returns the per-attempt deadline, capped at the request
// timeout. It is zero unless attempt_timeout_seconds is set: AttemptTimeout
// would otherwise fall back to the request timeout, which the request context
// already enforces.
func attemptDeadline(cfg config.Config) time.Duration {
	if cfg.Performance.AttemptTimeoutSeconds <= 0 {
		return 0
	}
	return cfg.Performance.AttemptTimeout(time.Duration(cfg.Retry.TimeoutSeconds) * time.Second)
}

// statusClientClosedRequest is nginx's 499: the client went away before the
// gateway could answer, so the failure is neither upstream nor ours.
const statusClientClosedRequest = 499

// proxyUnavailableMessage is the 503 message sent when the error a request
// finally failed with is tagged errProxyUnavailable: its last attempt never
// reached the upstream because the proxy route failed, or the anonymous lane
// had no proxy to try while none was healthy. Only that final error is
// inspected; earlier attempts may have failed for other reasons. The message
// points operators at their proxies instead of the upstream.
const proxyUnavailableMessage = "all proxies are unavailable; the upstream could not be reached"

// Gateway serves the local inference API for one configuration. It owns the
// proxy transports and the key and anonymous node pools built from that
// config; applying a new config builds a new Gateway (see RuntimeController)
// instead of mutating this one.
type Gateway struct {
	rotation   *rotation.Manager
	cfg        config.Config
	logger     *slog.Logger
	redactor   *config.Redactor
	transports *proxyTransports
	zenNodes   *upstreamNodes
	goNodes    *upstreamNodes
	anonymous  *anonymousNodes
	// warp, when non-nil, is the shared userspace WARP pool. Free-model
	// traffic on the anonymous lane and the Zen key tier leaves through it
	// instead of the configured proxies and transports.
	warp         *warp.Pool
	catalog      *models.ModelCatalog
	monitor      *telemetry.Metrics
	availability *models.AvailabilityRegistry
	// attemptTimeout bounds a whole upstream attempt (dial + write + headers
	// and, when the first-event wait is enabled, the first event), not just
	// the header wait. Zero arms no per-attempt deadline: each attempt is then
	// bounded only by the request-level budget.
	attemptTimeout time.Duration
	// freeTierBlock is how long an exit the free tier flagged stays out of the
	// anonymous cursor. Zero uses freeTierBlockTTL.
	freeTierBlock time.Duration
	// refreshMu prevents overlapping catalog refreshes across concurrent or scheduled callers.
	refreshMu              sync.Mutex
	resolveGoOAuth         func(context.Context) (*oauth.Connection, error)
	onGoOAuthUnauthorized  func(context.Context, oauth.Credential)
	resolveZenOAuth        func(context.Context) (*oauth.Connection, error)
	onZenOAuthUnauthorized func(context.Context, oauth.Credential)
}

// New builds a Gateway for cfg: one proxy transport per runtime proxy (a
// single direct transport when none is configured), Zen and Go key pools
// bound to those transports, the anonymous node pool and a model catalog. Its
// rotation manager is not persisted; RuntimeController replaces it with the
// shared one.
func New(cfg config.Config, logger *slog.Logger, monitor *telemetry.Metrics, warpPool *warp.Pool) (*Gateway, error) {
	if logger == nil {
		logger = slog.Default()
	}
	cfg.Rotation.Defaults()
	rotationManager, err := rotation.New("", cfg.Rotation)
	if err != nil {
		return nil, err
	}
	transports, err := transportPool(cfg.RuntimeProxies(), cfg.Performance, cfg.Performance.AttemptTimeout(time.Duration(cfg.Retry.TimeoutSeconds)*time.Second))
	if err != nil {
		return nil, err
	}
	cooldown := time.Duration(cfg.Performance.FailureCooldownSeconds) * time.Second
	zenKeys := cfg.ZenKeys
	if cfg.ZenOAuth != nil {
		zenKeys = nil
	}
	zenNodes, err := nodePool(zenKeys, transports, cooldown, cfg.ProxyBindings)
	if err != nil {
		return nil, fmt.Errorf("zen node pool: %w", err)
	}
	goKeys := cfg.GoKeys
	if cfg.GoOAuth != nil {
		goKeys = nil
	}
	goNodes, err := nodePool(goKeys, transports, cooldown, cfg.ProxyBindings)
	if err != nil {
		return nil, fmt.Errorf("go node pool: %w", err)
	}
	catalog := models.Catalog(cfg.Prefer, cfg.Models.Protocols)
	catalog.SetRefreshInterval(time.Duration(cfg.Models.RefreshSeconds) * time.Second)
	catalog.SetFreeOnly(cfg.Models.FreeOnly)
	redactor := config.SecretRedactor()
	redactor.Replace(cfg)
	gateway := &Gateway{
		cfg:            cfg,
		rotation:       rotationManager,
		logger:         logger,
		redactor:       redactor,
		transports:     transports,
		zenNodes:       zenNodes,
		goNodes:        goNodes,
		anonymous:      anonymousPool(cfg.Anonymous, transports, cooldown, anonymousBackoffFromConfig(cfg.Models.AnonymousBackoff)),
		warp:           warpPool,
		catalog:        catalog,
		monitor:        monitor,
		attemptTimeout: attemptDeadline(cfg),
		freeTierBlock:  time.Duration(cfg.Performance.FreeTierBlockSeconds) * time.Second,
	}
	gateway.restoreOAuthCatalog()
	return gateway, nil
}

// anonymousBackoffFromConfig converts the configured hours into the breaker's
// thresholds and durations. A nil block disables the breaker (threshold 0).
func anonymousBackoffFromConfig(cfg *config.AnonymousBackoffConfig) anonymousBackoff {
	if cfg == nil {
		return anonymousBackoff{}
	}
	return anonymousBackoff{
		threshold: int32(cfg.Threshold),
		base:      time.Duration(cfg.BaseHours) * time.Hour,
		max:       time.Duration(cfg.MaxHours) * time.Hour,
	}
}

// Handler returns the gateway's HTTP API: the server-key authenticated /v1
// model, inference and System One routes plus the open /healthz, wrapped in
// panic recovery.
func (g *Gateway) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/models", g.authenticate(g.handleModels))
	mux.HandleFunc("POST /v1/chat/completions", g.authenticate(g.handleInference(wire.Chat)))
	mux.HandleFunc("POST /v1/responses", g.authenticate(g.handleInference(wire.Responses)))
	mux.HandleFunc("POST /v1/messages", g.authenticate(g.handleInference(wire.Anthropic)))
	mux.HandleFunc("POST /v1/systemone", g.authenticate(g.handleSystemOne))
	mux.HandleFunc("GET /healthz", g.handleHealth)
	return telemetry.Recover(g.logger, mux)
}

// authenticate admits a request whose x-api-key header or Bearer token
// matches an enabled server key, and stores the caller's fingerprint in the
// request context and telemetry metadata. Anything else gets a 401 shaped for
// the endpoint: Anthropic for /v1/messages, Chat otherwise.
func (g *Gateway) authenticate(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		candidates := []string{strings.TrimSpace(r.Header.Get("x-api-key"))}
		if auth := r.Header.Get("Authorization"); strings.HasPrefix(strings.ToLower(auth), "bearer ") {
			candidates = append(candidates, strings.TrimSpace(auth[7:]))
		}
		matched := ""
		for _, key := range g.cfg.ServerKeys {
			if !g.cfg.ServerKeyEnabled(key) {
				continue
			}
			for _, candidate := range candidates {
				if len(candidate) == len(key) && subtle.ConstantTimeCompare([]byte(candidate), []byte(key)) == 1 {
					matched = key
				}
			}
		}
		if matched == "" {
			protocol := wire.Chat
			if r.URL.Path == "/v1/messages" {
				protocol = wire.Anthropic
			}
			wire.WriteError(w, protocol, http.StatusUnauthorized, "invalid local API key", "authentication_error", "")
			return
		}
		// The Playground borrows the first enabled key to pass this check, so
		// its traffic gets its own bucket instead of being billed to that key.
		caller := config.Fingerprint(matched)
		if isDiagnosticRequest(r.Context()) {
			caller = telemetry.PlaygroundServerKey
		}
		if meta := telemetry.MetaFromRequest(r); meta != nil {
			meta.ServerKeyID = caller
		}
		next(w, r.WithContext(context.WithValue(r.Context(), callerContextKey{}, caller)))
	}
}

type callerContextKey struct{}

// callerScope returns the authenticated caller that request identities are
// scoped to, so different server keys never share an upstream session.
func callerScope(ctx context.Context) string {
	caller, _ := ctx.Value(callerContextKey{}).(string)
	return caller
}

// handleInference serves a message endpoint whose wire protocol is external.
// A rotation group alias is handed to handleRotation. Any other model is
// routed through the catalog, encoded per upstream tier, sent through
// doUpstream and translated back into external, streaming or not.
type requestShapeContextKey struct{}

type requestShape struct {
	shaped  bool
	renames *wire.ToolRenames
}

func setRequestShape(ctx context.Context, shaped bool, renames *wire.ToolRenames) {
	if state, ok := ctx.Value(requestShapeContextKey{}).(*requestShape); ok {
		state.shaped, state.renames = shaped, renames
	}
	if meta := telemetry.MetaFromContext(ctx); meta != nil {
		meta.Shaped = shaped
		meta.ToolRenames = renames.Count()
	}
}

func requestShapeFrom(ctx context.Context) requestShape {
	if state, ok := ctx.Value(requestShapeContextKey{}).(*requestShape); ok && state != nil {
		return *state
	}
	return requestShape{}
}

func (g *Gateway) handleInference(external wire.Protocol) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		r = r.WithContext(context.WithValue(r.Context(), requestShapeContextKey{}, &requestShape{}))
		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxRequestBody))
		if err != nil {
			wire.WriteError(w, external, http.StatusBadRequest, "request body is too large or unreadable", "invalid_request_error", "")
			return
		}
		var payload map[string]any
		if err := json.Unmarshal(body, &payload); err != nil {
			wire.WriteError(w, external, http.StatusBadRequest, "request body must be a JSON object", "invalid_request_error", "")
			return
		}
		var strippedEnvironment bool
		r, strippedEnvironment, err = g.withClientEnvironment(r, payload, external)
		if err != nil {
			wire.WriteError(w, external, http.StatusBadRequest, err.Error(), "invalid_request_error", "client_environment")
			return
		}
		model := jsonutil.StringAt(payload, "model")
		meta := telemetry.MetaFromRequest(r)
		if meta != nil {
			meta.Model = model
		}
		if model == "" {
			wire.WriteError(w, external, http.StatusBadRequest, "model is required", "invalid_request_error", "model")
			return
		}
		if id := g.rotation.GroupID(model); id != "" {
			g.handleRotation(w, r, external, payload, id, model)
			return
		}
		oauthModel := false
		for _, connection := range []*oauth.Connection{g.cfg.GoOAuth, g.cfg.ZenOAuth} {
			if connection != nil {
				_, included := connection.Routes[model]
				oauthModel = oauthModel || included
			}
		}
		if !oauthModel && !g.catalog.Supported(model) {
			// A model the catalog has never heard of is a bad model NAME: 404
			// tells a client to pick a different model. A model the catalog
			// knows but cannot serve is a capability or routing problem, and
			// the old 400 phrasing ("the model uses an upstream protocol that
			// opencode2api does not expose") is accurate for it. The old code
			// returned that 400 for BOTH, so a request for a model the
			// upstream retired (it answers 410 Gone) looked like a gateway
			// capability bug and clients retried forever.
			if g.catalog.Known(model) {
				wire.WriteError(w, external, http.StatusBadRequest, "the model uses an upstream protocol that opencode2api does not expose", "invalid_request_error", "model")
			} else {
				wire.WriteError(w, external, http.StatusNotFound, fmt.Sprintf("model %q was not found in the upstream model catalog", model), "model_not_found", "model")
			}
			return
		}
		route, err := g.routeForModel(model, "")
		if override, selected := debugKeyOverrideFrom(r.Context()); selected {
			// A per-key diagnostic must not silently be served by another key,
			// another tier or the anonymous lane.
			route, err = g.routeForModel(model, override.Tier)
		}
		if err != nil {
			var oauthError *oauth.OAuthError
			if errors.As(err, &oauthError) {
				wire.WriteError(w, external, http.StatusServiceUnavailable, oauthError.Error(), "oauth_auth_error", "")
				return
			}
			wire.WriteError(w, external, http.StatusBadRequest, err.Error(), "invalid_request_error", "model")
			return
		}
		if meta != nil {
			meta.Tier = string(route.Tier)
			meta.Protocol = route.Protocol
		}
		// A System One model has no message-shaped equivalent, so a decision
		// payload submitted on a message endpoint is relayed verbatim instead of
		// being converted. This keeps the model reachable for clients that can
		// only address /v1/chat/completions or /v1/responses — for example a
		// gateway whose OpenAI platform pins every request to Responses.
		if route.Protocol == wire.SystemOne {
			if len(jsonutil.MapAt(payload, "questions")) == 0 || payload["state"] == nil {
				wire.WriteError(w, external, http.StatusBadRequest, "this model uses System One decisions, not chat; send state and typed questions to /v1/systemone", "invalid_request_error", "model")
				return
			}
			if strippedEnvironment {
				// This path forwards raw bytes rather than converting payload.
				body, err = jsonutil.Marshal(payload)
				if err != nil {
					wire.WriteError(w, external, http.StatusBadRequest, "request body could not be encoded", "invalid_request_error", "")
					return
				}
			}
			g.forwardSystemOne(w, r, body, payload, model, route)
			return
		}
		bodies, err := g.prepareRouteBodies(external, route, payload)
		if err != nil {
			wire.WriteError(w, external, http.StatusBadRequest, err.Error(), "invalid_request_error", "")
			return
		}
		ids := identity.DeriveRequestIDs(r, payload, callerScope(r.Context()))
		if meta != nil {
			meta.Request = ids.Request
			meta.Session = ids.Session
		}
		stream := jsonutil.BoolAt(payload, "stream")
		requestCtx, cancel := context.WithTimeout(r.Context(), time.Duration(g.cfg.Retry.TimeoutSeconds)*time.Second)
		defer cancel()
		resp, upstreamRoute, err := g.doUpstream(requestCtx, route, bodies, ids)
		if err != nil {
			// The error branch never forwards the last response body, so close
			// it here; otherwise a block or a paused lane leaks one upstream
			// connection on every request.
			if resp != nil && resp.Body != nil {
				httpx.DrainAndClose(resp.Body)
			}
			finalTier := route.Tier
			if meta != nil && meta.Tier != "" {
				finalTier = config.Tier(meta.Tier)
			}
			keyID, channel, anonymous := requestCredential(requestCtx)
			// A downstream disconnect is not an upstream failure: report the
			// real cause so telemetry and clients see a cancel, not a 502.
			if !errors.Is(err, context.DeadlineExceeded) && wire.ClientCanceled(r.Context(), err) {
				g.logger.Debug("client canceled before upstream response", "component", "upstream", "event", "request_canceled", "request_id", ids.Request, "tier", finalTier, "key_id", keyID, "channel", channel, "anonymous", anonymous)
				if meta != nil {
					meta.Outcome = "client_canceled"
				}
				wire.WriteError(w, external, statusClientClosedRequest, "client closed request", "client_canceled", ids.Request)
				return
			}
			g.logger.Warn("all upstream attempts failed", "component", "upstream", "event", "request_failed", "request_id", ids.Request, "tier", finalTier, "key_id", keyID, "channel", channel, "anonymous", anonymous, "error", err)
			// The final attempt never reached the upstream because its proxy
			// route failed; report that instead of blaming the upstream with
			// a 502.
			if errors.Is(err, errProxyUnavailable) {
				wire.WriteError(w, external, http.StatusServiceUnavailable, proxyUnavailableMessage, "proxy_error", ids.Request)
				return
			}
			if errors.Is(err, errWARPUnavailable) {
				wire.WriteError(w, external, http.StatusServiceUnavailable, warpUnavailableMessage, "warp_unavailable", ids.Request)
				return
			}
			// An exhausted request budget is a timeout, not a bad gateway: the
			// distinction matters to clients that retry on 502.
			if errors.Is(err, context.DeadlineExceeded) {
				// A write-phase failure means the upstream never finished
				// reading the request body: the payload is too large. Report
				// it as 413 so a client that can shrink the request (a harness
				// that strips oversized inline images) knows to shrink it
				// instead of retrying the same oversized payload forever. A
				// header- or first-event-phase failure is the upstream being
				// slow, which is not the client's fault, and stays a 504.
				status, message, code := timeoutStatus(err, requestCtx.Err() == nil)
				wire.WriteError(w, external, status, message, code, ids.Request)
				return
			}
			var oauthError *oauth.OAuthError
			if errors.As(err, &oauthError) {
				wire.WriteError(w, external, http.StatusServiceUnavailable, oauthError.Error(), "oauth_auth_error", ids.Request)
				return
			}
			// Every exit this request could use is under the free tier's IP
			// block. A 502 would read as a transient upstream fault and invite
			// the client to retry into the same penalty, so answer with the
			// block itself.
			if errors.Is(err, errFreeTierIPBlocked) {
				wire.WriteError(w, external, http.StatusServiceUnavailable, freeTierBlockedMessage, "free_tier_ip_blocked", ids.Request)
				return
			}
			// The anonymous lane's circuit breaker is open. Report the pause
			// distinctly so the operator does not look for a credential or a
			// model problem in the upstream error.
			if errors.Is(err, errAnonymousLanePaused) {
				wire.WriteError(w, external, http.StatusServiceUnavailable, anonymousLanePausedMessage, "free_tier_lane_paused", ids.Request)
				return
			}
			wire.WriteError(w, external, http.StatusBadGateway, "all upstream attempts failed", "upstream_error", ids.Request)
			return
		}
		defer resp.Body.Close()
		if meta != nil {
			meta.Tier = string(upstreamRoute.Tier)
			meta.Protocol = upstreamRoute.Protocol
		}
		w.Header().Set("x-request-id", ids.Request)
		if resp.StatusCode/100 != 2 {
			g.copyErrorResponse(w, external, resp, ids.Request)
			return
		}
		shape := requestShapeFrom(r.Context())
		toolRenames := shape.renames
		if stream {
			if meta != nil {
				meta.Stream = true
			}
			if g.monitor != nil {
				g.monitor.BeginStream()
				defer g.monitor.EndStream()
			}
			w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
			w.Header().Set("Cache-Control", "no-cache")
			w.Header().Set("X-Accel-Buffering", "no")
			streamBody := wire.RenameStreamReader(resp.Body, upstreamRoute.Protocol, toolRenames)
			var usage wire.Usage
			var usageReported bool
			if external == upstreamRoute.Protocol {
				streamWriter := w
				if flusher, ok := w.(http.Flusher); ok {
					streamWriter = &deferredStreamWriter{ResponseWriter: w, flusher: flusher, status: resp.StatusCode}
				}
				usage, usageReported, err = wire.ForwardStream(r.Context(), streamWriter, streamBody, upstreamRoute.Protocol, model)
			} else {
				w.WriteHeader(resp.StatusCode)
				usage, usageReported, err = wire.TranscodeStream(r.Context(), w, streamBody, upstreamRoute.Protocol, external, model)
			}
			if meta != nil {
				meta.Usage, meta.UsageReported = usage, usageReported
				if err != nil {
					meta.Outcome = "stream_error"
					if wire.ClientCanceled(r.Context(), err) {
						meta.Outcome = "client_canceled"
					}
				}
			}
			if err != nil && !errors.Is(err, context.Canceled) {
				g.logger.Warn("downstream stream ended with an error", "component", "stream", "event", "stream_failed", "request_id", ids.Request, "model", model, "tier", upstreamRoute.Tier, "error", err)
			}
			return
		}
		responseBody, err := io.ReadAll(io.LimitReader(resp.Body, (64<<20)+1))
		if err != nil {
			wire.WriteError(w, external, http.StatusBadGateway, "failed to read upstream response", "upstream_error", ids.Request)
			return
		}
		if len(responseBody) > 64<<20 {
			wire.WriteError(w, external, http.StatusBadGateway, "upstream response exceeds 64 MiB", "upstream_error", ids.Request)
			return
		}
		if upstreamRoute.Anonymous || shape.shaped {
			// The anonymous lane, and a key-tier request shaped like it, is
			// force-streamed upstream (see prepareAnonymousBody); collapse
			// the events back into the single document this non-streaming
			// client asked for.
			collapsed, err := wire.CollapseStream(bytes.NewReader(responseBody), upstreamRoute.Protocol, model)
			if err != nil {
				g.logger.Warn("forced stream collapse failed", "component", "conversion", "event", "stream_collapse_failed", "request_id", ids.Request, "model", model, "anonymous", upstreamRoute.Anonymous, "source_protocol", upstreamRoute.Protocol, "error", err)
				wire.WriteError(w, external, http.StatusBadGateway, "unsupported upstream response", "upstream_error", ids.Request)
				return
			}
			responseBody = collapsed
		}
		responseBody = wire.RenameResponseTool(responseBody, upstreamRoute.Protocol, toolRenames)
		if usage, reported := wire.ResponseUsage(upstreamRoute.Protocol, responseBody); meta != nil {
			meta.Usage, meta.UsageReported = usage, reported
		}
		if external != upstreamRoute.Protocol {
			responseBody, err = wire.ConvertResponse(upstreamRoute.Protocol, external, responseBody)
			if err != nil {
				g.logger.Warn("response protocol conversion failed", "component", "conversion", "event", "response_conversion_failed", "request_id", ids.Request, "model", model, "source_protocol", upstreamRoute.Protocol, "target_protocol", external, "error", err)
				wire.WriteError(w, external, http.StatusBadGateway, "unsupported upstream response", "upstream_error", ids.Request)
				return
			}
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(resp.StatusCode)
		_, _ = w.Write(responseBody)
	}
}

// deferredStreamWriter keeps the upstream success status pending while the
// first SSE frame is validated, allowing an invalid prelude to become a 502.
type deferredStreamWriter struct {
	http.ResponseWriter
	flusher   http.Flusher
	status    int
	committed bool
}

func (w *deferredStreamWriter) WriteHeader(status int) {
	if !w.committed {
		w.committed = true
		w.ResponseWriter.WriteHeader(status)
	}
}

func (w *deferredStreamWriter) Write(body []byte) (int, error) {
	w.WriteHeader(w.status)
	return w.ResponseWriter.Write(body)
}

func (w *deferredStreamWriter) Flush() {
	w.WriteHeader(w.status)
	w.flusher.Flush()
}

// handleSystemOne serves System One decision requests on their own endpoint.
// Only models whose upstream protocol is System One can be served here; a chat
// or responses model belongs on its own endpoint, where the bridge can convert
// it.
func (g *Gateway) handleSystemOne(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxRequestBody))
	if err != nil {
		wire.WriteError(w, wire.SystemOne, http.StatusBadRequest, "request body is too large or unreadable", "invalid_request_error", "")
		return
	}
	var payload map[string]any
	if err := json.Unmarshal(body, &payload); err != nil {
		wire.WriteError(w, wire.SystemOne, http.StatusBadRequest, "request body must be a JSON object", "invalid_request_error", "")
		return
	}
	var strippedEnvironment bool
	r, strippedEnvironment, err = g.withClientEnvironment(r, payload, wire.SystemOne)
	if err != nil {
		wire.WriteError(w, wire.SystemOne, http.StatusBadRequest, err.Error(), "invalid_request_error", "client_environment")
		return
	}
	if strippedEnvironment {
		body, err = jsonutil.Marshal(payload)
		if err != nil {
			wire.WriteError(w, wire.SystemOne, http.StatusBadRequest, "request body could not be encoded", "invalid_request_error", "")
			return
		}
	}
	model := jsonutil.StringAt(payload, "model")
	if meta := telemetry.MetaFromRequest(r); meta != nil {
		meta.Model = model
	}
	if model == "" {
		wire.WriteError(w, wire.SystemOne, http.StatusBadRequest, "model is required", "invalid_request_error", "model")
		return
	}
	if !g.catalog.Supported(model) {
		// Same split as the chat path: a model the catalog has never heard of
		// is a bad model NAME (404), a model it knows but cannot serve is a
		// capability or routing problem (400).
		if g.catalog.Known(model) {
			wire.WriteError(w, wire.SystemOne, http.StatusBadRequest, "the model uses an upstream protocol that opencode2api does not expose", "invalid_request_error", "model")
		} else {
			wire.WriteError(w, wire.SystemOne, http.StatusNotFound, fmt.Sprintf("model %q was not found in the upstream model catalog", model), "model_not_found", "model")
		}
		return
	}
	route, err := g.routeForModel(model, "")
	if err != nil {
		wire.WriteError(w, wire.SystemOne, http.StatusBadRequest, err.Error(), "invalid_request_error", "model")
		return
	}
	if route.Protocol != wire.SystemOne {
		wire.WriteError(w, wire.SystemOne, http.StatusBadRequest, fmt.Sprintf("the model does not use the %s protocol", wire.SystemOne), "invalid_request_error", "model")
		return
	}
	g.forwardSystemOne(w, r, body, payload, model, route)
}

// forwardSystemOne relays a System One decision payload verbatim to the
// upstream systemone endpoint and returns the typed answer document unchanged.
// The payload pairs a free-form state with typed questions, which no
// message-shaped upstream protocol accepts, so it is never translated. Answers
// are non-streaming today; a streaming upstream reply is still relayed.
func (g *Gateway) forwardSystemOne(w http.ResponseWriter, r *http.Request, body []byte, payload map[string]any, model string, route models.Route) {
	meta := telemetry.MetaFromRequest(r)
	if meta != nil {
		meta.Model = model
		meta.Tier = string(route.Tier)
		meta.Protocol = route.Protocol
	}
	// One verbatim body serves every tier: a decision payload has no per-tier
	// encoding, so no protocol conversion is attempted.
	bodies := make(map[config.Tier][]byte, len(route.KeyTiers)+1)
	bodies[route.Tier] = body
	for _, tier := range route.KeyTiers {
		bodies[tier] = body
	}
	ids := identity.DeriveRequestIDs(r, payload, callerScope(r.Context()))
	if meta != nil {
		meta.Request = ids.Request
		meta.Session = ids.Session
	}
	requestCtx, cancel := context.WithTimeout(r.Context(), time.Duration(g.cfg.Retry.TimeoutSeconds)*time.Second)
	defer cancel()
	resp, upstreamRoute, err := g.doUpstream(requestCtx, route, bodies, ids)
	if err != nil {
		finalTier := route.Tier
		if meta != nil && meta.Tier != "" {
			finalTier = config.Tier(meta.Tier)
		}
		keyID, channel, anonymous := requestCredential(requestCtx)
		if !errors.Is(err, context.DeadlineExceeded) && wire.ClientCanceled(r.Context(), err) {
			g.logger.Debug("client canceled before upstream response", "component", "upstream", "event", "request_canceled", "request_id", ids.Request, "tier", finalTier, "key_id", keyID, "channel", channel, "anonymous", anonymous)
			if meta != nil {
				meta.Outcome = "client_canceled"
			}
			wire.WriteError(w, wire.SystemOne, statusClientClosedRequest, "client closed request", "client_canceled", ids.Request)
			return
		}
		g.logger.Warn("all upstream attempts failed", "component", "upstream", "event", "request_failed", "request_id", ids.Request, "tier", finalTier, "key_id", keyID, "channel", channel, "anonymous", anonymous, "error", err)
		if errors.Is(err, errProxyUnavailable) {
			wire.WriteError(w, wire.SystemOne, http.StatusServiceUnavailable, proxyUnavailableMessage, "proxy_error", ids.Request)
			return
		}
		if errors.Is(err, errWARPUnavailable) {
			wire.WriteError(w, wire.SystemOne, http.StatusServiceUnavailable, warpUnavailableMessage, "warp_unavailable", ids.Request)
			return
		}
		if errors.Is(err, context.DeadlineExceeded) {
			// Same split as the chat path: a write-phase failure means the
			// payload is too large (413), every other phase is a slow
			// upstream (504).
			status, message, code := timeoutStatus(err, requestCtx.Err() == nil)
			wire.WriteError(w, wire.SystemOne, status, message, code, ids.Request)
			return
		}
		wire.WriteError(w, wire.SystemOne, http.StatusBadGateway, "all upstream attempts failed", "upstream_error", ids.Request)
		return
	}
	defer resp.Body.Close()
	if meta != nil {
		meta.Tier = string(upstreamRoute.Tier)
		meta.Protocol = upstreamRoute.Protocol
	}
	w.Header().Set("x-request-id", ids.Request)
	if resp.StatusCode/100 != 2 {
		g.copyErrorResponse(w, wire.SystemOne, resp, ids.Request)
		return
	}
	if contentType := resp.Header.Get("Content-Type"); strings.HasPrefix(contentType, "text/event-stream") {
		if meta != nil {
			meta.Stream = true
		}
		w.Header().Set("Content-Type", contentType)
		w.Header().Set("Cache-Control", "no-cache")
		w.WriteHeader(resp.StatusCode)
		_, _ = io.Copy(w, resp.Body)
		return
	}
	responseBody, err := io.ReadAll(io.LimitReader(resp.Body, (64<<20)+1))
	if err != nil {
		wire.WriteError(w, wire.SystemOne, http.StatusBadGateway, "failed to read upstream response", "upstream_error", ids.Request)
		return
	}
	if len(responseBody) > 64<<20 {
		wire.WriteError(w, wire.SystemOne, http.StatusBadGateway, "upstream response exceeds 64 MiB", "upstream_error", ids.Request)
		return
	}
	if usage, reported := wire.ResponseUsage(upstreamRoute.Protocol, responseBody); meta != nil {
		meta.Usage, meta.UsageReported = usage, reported
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(resp.StatusCode)
	_, _ = w.Write(responseBody)
}

// prepareRouteBodies encodes input once for each key tier the route may use,
// the preferred tier first and then its KeyTiers, in that tier's upstream
// protocol and with any forced reasoning effort applied. A fallback tier the
// request cannot be converted for is skipped; only a conversion failure on
// the preferred tier is an error.
func (g *Gateway) prepareRouteBodies(from wire.Protocol, route models.Route, input map[string]any) (map[config.Tier][]byte, error) {
	tiers := make([]config.Tier, 0, len(route.KeyTiers)+1)
	seen := make(map[config.Tier]bool, len(route.KeyTiers)+1)
	addTier := func(tier config.Tier) {
		if tier != config.TierZen && tier != config.TierGo || seen[tier] {
			return
		}
		seen[tier] = true
		tiers = append(tiers, tier)
	}
	addTier(route.Tier)
	for _, tier := range route.KeyTiers {
		addTier(tier)
	}
	if len(tiers) == 0 {
		return nil, errors.New("no usable upstream tier")
	}
	bodies := make(map[config.Tier][]byte, len(tiers))
	for _, tier := range tiers {
		protocol := route.ProtocolFor(tier)
		baseURL := g.cfg.Upstream.Zen
		if tier == config.TierGo {
			baseURL = g.cfg.Upstream.Go
		}
		if connection := g.tierOAuth(tier); connection != nil && !route.Anonymous {
			oauthRoute, ok := connection.Routes[route.ID]
			if !ok {
				return nil, errors.New("model is not included in the connected OAuth plan")
			}
			baseURL = oauthRoute.BaseURL
		}
		upstreamPayload, err := wire.PrepareRequest(from, protocol, input, baseURL)
		if err != nil {
			if tier != route.Tier {
				// A fallback tier may use a stricter wire format than the
				// preferred tier. Do not reject a request before the preferred
				// upstream has even been tried; that tier is attempted only if
				// the request actually falls back.
				g.logger.Debug("skipping fallback tier with incompatible request shape", "component", "conversion", "event", "fallback_tier_skipped", "model", jsonutil.StringAt(input, "model"), "tier", tier, "protocol", protocol, "error", err)
				continue
			}
			return nil, fmt.Errorf("prepare %s upstream request: %w", tier, err)
		}
		if effort := g.resolvedEffort(jsonutil.StringAt(upstreamPayload, "model"), tier, protocol); effort != "" {
			wire.ForcedEffort(protocol, upstreamPayload, effort)
		}
		encoded, err := jsonutil.Marshal(upstreamPayload)
		if err != nil {
			return nil, errors.New("request contains unsupported JSON values")
		}
		bodies[tier] = encoded
	}
	return bodies, nil
}

// copyErrorResponse relays a non-2xx upstream reply as an error in the
// client's protocol. It keeps the status and any Retry-After, and takes the
// message from a JSON body's error.message or message, falling back to the
// status text.
func (g *Gateway) copyErrorResponse(w http.ResponseWriter, protocol wire.Protocol, resp *http.Response, requestID string) {
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if retryAfter := resp.Header.Get("Retry-After"); retryAfter != "" {
		w.Header().Set("Retry-After", g.redactor.String(retryAfter))
	}
	message := http.StatusText(resp.StatusCode)
	var value map[string]any
	if json.Unmarshal(body, &value) == nil {
		message = jsonutil.FirstString(jsonutil.StringAt(value, "error", "message"), jsonutil.StringAt(value, "message"), message)
	}
	// Error bodies may echo the credential that the upstream rejected. Decode
	// first so escaped JSON strings receive the same redaction as plain text.
	wire.WriteError(w, protocol, resp.StatusCode, g.redactor.String(message), "upstream_error", requestID)
}

internal/gateway/rotation.go:
package gateway

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	"opencode2api/internal/config"
	"opencode2api/internal/identity"
	"opencode2api/internal/jsonutil"
	"opencode2api/internal/models"
	"opencode2api/internal/oauth"
	wire "opencode2api/internal/protocol"
	"opencode2api/internal/rotation"
	"opencode2api/internal/telemetry"
)

// syncRotation tells the rotation manager which catalog models the Go tier can
// serve right now: every model with a Go route except System One models, and
// none while no Go key is configured.
func (g *Gateway) syncRotation() {
	available := map[string]bool{}
	for _, model := range g.catalog.List() {
		if route, err := g.routeForModel(model, config.TierGo); err == nil && route.Protocol != wire.SystemOne {
			available[model] = true
		}
	}
	g.rotation.Sync(available)
}

// RotationSnapshot resyncs the rotation groups with the current catalog and
// returns their state.
func (m *RuntimeController) RotationSnapshot() rotation.Snapshot {
	r := m.current.Load()
	r.gateway.syncRotation()
	return m.rotation.Snapshot()
}

// SelectRotation manually switches rotation group id to model, clearing any
// pause on it, after resyncing the groups with the current catalog. model
// must be one of the group's currently available models.
func (m *RuntimeController) SelectRotation(id, model string) error {
	m.updateMu.Lock()
	defer m.updateMu.Unlock()
	m.current.Load().gateway.syncRotation()
	return m.rotation.Manual(id, model)
}

// quotaError reports whether a failed rotation attempt hit a quota or rate
// limit, which pauses the model for its Retry-After instead of spending the
// request's ordinary-failure budget. Any 429 counts; otherwise only explicit
// quota markers in the body do, since ordinary provider errors must keep
// their budget.
func quotaError(status int, body string) bool {
	if status == 429 {
		return true
	}
	body = strings.ToLower(body)
	for _, marker := range []string{"insufficient_quota", "quota_exceeded", "quota exceeded", "quota exhausted", "rate_limit", "rate limit", "rate-limit", "usage_limit", "usage limit", "insufficient balance", "credit balance is too low", "额度不足", "配额已用尽"} {
		if strings.Contains(body, marker) {
			return true
		}
	}
	return false
}

// groupAttempt is the outcome of one rotation attempt. quota marks a quota or
// rate-limit failure, committed means the reply already reached the client,
// pause is how long a quota failure pauses the model, and reason labels the
// attempt record.
type groupAttempt struct {
	err              error
	quota, committed bool
	pause            time.Duration
	reason           string
}

// handleRotation serves a request addressed to a rotation group alias on the
// Go tier. It walks the group's usable models from the current one, giving
// each up to three single-call attempts. A quota or rate-limit failure pauses
// the model for its Retry-After (60 seconds without one) and moves on to the
// next model; a model that fails a third time for another reason is paused
// for 15 seconds. The walk ends on success, once a reply has been committed
// downstream, once three models have failed for ordinary reasons, when no
// usable model is left, or when the request budget runs out. Unless the client
// went away, a request left without a reply then gets a 503, or a 504 when
// the budget ran out.
func (g *Gateway) handleRotation(w http.ResponseWriter, r *http.Request, external wire.Protocol, payload map[string]any, id, alias string) {
	g.syncRotation()
	ctx, cancel := context.WithTimeout(r.Context(), time.Duration(g.cfg.Retry.TimeoutSeconds)*time.Second)
	defer cancel()
	ids := identity.DeriveRequestIDs(r, payload, callerScope(r.Context()))
	meta := telemetry.MetaFromRequest(r)
	if meta != nil {
		meta.Request = ids.Request
		meta.Session = ids.Session
		meta.ModelAlias = alias
	}
	if g.cfg.GoOAuth != nil && g.cfg.GoOAuth.NeedsLogin {
		wire.WriteError(w, external, http.StatusServiceUnavailable, (&oauth.OAuthError{Code: "invalid_grant"}).Error(), "oauth_auth_error", ids.Request)
		return
	}
	visited := map[string]bool{}
	ordinaryModels, total := 0, 0
	for ctx.Err() == nil {
		token, ok := g.rotation.Select(id, visited)
		if !ok {
			break
		}
		visited[token.Model] = true
		route, err := g.routeForModel(token.Model, config.TierGo)
		if err != nil {
			var oauthError *oauth.OAuthError
			if errors.As(err, &oauthError) {
				wire.WriteError(w, external, http.StatusServiceUnavailable, oauthError.Error(), "oauth_auth_error", ids.Request)
				return
			}
			continue
		}
		counted := false
		for n := 1; n <= 3 && ctx.Err() == nil; n++ {
			total++
			if meta != nil {
				meta.Model = token.Model
				meta.Tier = "go"
				meta.Protocol = route.Protocol
				meta.Attempts = total
				meta.Usage = wire.Usage{}
				meta.UsageReported = false
			}
			result := g.rotationAttempt(ctx, w, r, external, payload, alias, route, ids, total)
			outcome := result.reason
			if result.err == nil {
				outcome = "success"
			}
			var clientWrite *wire.ClientWriteError
			canceled := r.Context().Err() != nil || errors.As(result.err, &clientWrite)
			if canceled {
				outcome = "client_canceled"
				if meta != nil {
					meta.Outcome = outcome
				}
			}
			g.rotation.Record(rotation.Attempt{Request: ids.Request, Alias: alias, Model: token.Model, Number: total, Outcome: outcome})
			if state := g.rotation.Snapshot(); state.PersistenceError != "" {
				g.logger.Error("rotation state persistence failed", "component", "rotation", "event", "rotation_persistence_failed")
			}
			g.logger.Info("model rotation attempt", "component", "rotation", "event", "rotation_attempt", "request_id", ids.Request, "alias", alias, "model", token.Model, "attempt", total, "reason", outcome)
			if canceled {
				return
			}
			if result.err == nil {
				return
			}
			var oauthError *oauth.OAuthError
			if errors.As(result.err, &oauthError) {
				wire.WriteError(w, external, http.StatusServiceUnavailable, oauthError.Error(), "oauth_auth_error", ids.Request)
				return
			}
			if g.cfg.GoOAuth != nil && result.reason == "oauth_auth_error" {
				return
			}
			if result.committed {
				if meta != nil {
					meta.Outcome = "stream_error"
				}
				pause := 15 * time.Second
				if result.quota {
					pause = result.pause
				}
				g.rotation.Fail(token, pause, result.reason)
				return
			}
			if ctx.Err() != nil {
				g.rotation.Fail(token, 15*time.Second, "request_timeout")
				break
			}
			if result.quota {
				g.rotation.Fail(token, result.pause, result.reason)
				break
			}
			if !counted {
				ordinaryModels++
				counted = true
			}
			if n == 3 {
				g.rotation.Fail(token, 15*time.Second, result.reason)
			}
		}
		if ordinaryModels >= 3 {
			break
		}
	}
	if r.Context().Err() != nil {
		return
	}
	status := http.StatusServiceUnavailable
	message := "该分组暂无可用模型（已暂停、下架、额度不足或重试次数已用尽），请稍后重试"
	if ctx.Err() != nil {
		status = http.StatusGatewayTimeout
		message = "分组请求整体超时"
	}
	wire.WriteError(w, external, status, message, "rotation_unavailable", ids.Request)
}

// rotationAttempt makes one upstream call for a rotation group model with the
// attempt-th key the session's Go cursor yields. Nothing reaches the client
// unless the first useful output (for a non-streaming reply, the whole body)
// arrives within the rotation's first_output_seconds, and the reply names the
// group alias as its model.
func (g *Gateway) rotationAttempt(parent context.Context, w http.ResponseWriter, original *http.Request, external wire.Protocol, payload map[string]any, alias string, route models.Route, ids identity.RequestIDs, attempt int) groupAttempt {
	result := groupAttempt{reason: "upstream_error", pause: 60 * time.Second}
	ctx, cancel := context.WithCancel(parent)
	defer cancel()
	seconds := g.rotation.Snapshot().FirstOutputSeconds
	timer := time.AfterFunc(time.Duration(seconds)*time.Second, cancel)
	defer timer.Stop()
	copyPayload := make(map[string]any, len(payload))
	for k, v := range payload {
		copyPayload[k] = v
	}
	copyPayload["model"] = route.ID
	bodies, err := g.prepareRouteBodies(external, route, copyPayload)
	if err != nil {
		result.err = err
		result.reason = "request_conversion_error"
		return result
	}
	var resp *http.Response
	var toolRenames *wire.ToolRenames
	shaped := false
	if g.cfg.GoOAuth != nil {
		resp, err = g.oauthAttempt(ctx, route, bodies[config.TierGo], ids, attempt, attempt-1, 0)
	} else {
		var body []byte
		body, toolRenames, shaped = g.shapeKeyBody(ctx, bodies[config.TierGo], route, config.TierGo)
		setRequestShape(parent, shaped, toolRenames)
		cursor := g.goNodes.CursorFor(ids.Session)
		var node *upstreamNode
		for selection := 0; selection < attempt; selection++ {
			node = cursor.Next()
		}
		if node == nil {
			result.err = errors.New("no Go key")
			return result
		}
		proxy := g.goNodes.Proxy(node)
		if proxy == nil {
			result.err = errors.New("no proxy")
			return result
		}
		req, requestErr := upstreamRequest(ctx, g.cfg.Upstream.Go, route.Protocol, body, ids, node.key)
		if requestErr != nil {
			result.err = requestErr
			return result
		}
		req.GetBody = nil
		client := *proxy.client
		client.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
		setRequestCredential(parent, config.TierGo, config.KeyDisplayID(node.key), "key", false, proxy)
		started := time.Now()
		if proxy.pool {
			req.Close = true
		}
		resp, err = doInferenceAttempt(&client, req, 0, g.attemptTimeout)
		if err != nil && ctx.Err() != nil && parent.Err() == nil && !isProxyFailure(err) {
			err = errFirstEventTimeout
		}
		g.recordUpstreamAttempt(parent, route, ids, attempt, config.KeyDisplayID(node.key), "key", false, proxy, resp, err, time.Since(started))
		if parent.Err() == nil {
			g.observeKeyResult(parent, g.goNodes, node, proxy, resp, err)
		}
	}
	if err != nil && ctx.Err() != nil && parent.Err() == nil && !isProxyFailure(err) {
		err = errFirstEventTimeout
	}
	if resp != nil {
		defer resp.Body.Close()
	}
	if err != nil {
		result.err = err
		var oauthError *oauth.OAuthError
		if errors.As(err, &oauthError) {
			result.reason = "oauth_auth_error"
		} else if errors.Is(err, errFirstEventTimeout) || ctx.Err() != nil {
			result.reason = "first_output_timeout"
		}
		return result
	}
	if g.cfg.GoOAuth != nil && resp.StatusCode == http.StatusUnauthorized {
		w.Header().Set("x-request-id", ids.Request)
		g.copyErrorResponse(w, external, resp, ids.Request)
		result.err = errors.New("Go OAuth authorization was rejected")
		result.reason = "oauth_auth_error"
		result.committed = true
		return result
	}
	retryAfter := resp.Header.Get("Retry-After")
	if pause := parseRetryAfter(retryAfter); pause > 0 {
		result.pause = pause
	} else if strings.TrimSpace(retryAfter) == "0" {
		result.pause = 0
	} else if _, err := http.ParseTime(retryAfter); err == nil {
		result.pause = 0
	}
	if resp.StatusCode/100 != 2 {
		b, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
		result.err = fmt.Errorf("upstream HTTP %d", resp.StatusCode)
		result.quota = quotaError(resp.StatusCode, string(b))
		result.reason = fmt.Sprintf("http_%d", resp.StatusCode)
		if result.quota {
			result.reason = "quota_or_rate_limit"
		}
		return result
	}
	stream := jsonutil.BoolAt(payload, "stream")
	ready := func() error {
		if !timer.Stop() || ctx.Err() != nil {
			return context.DeadlineExceeded
		}
		w.Header().Set("X-Resolved-Model", route.ID)
		w.Header().Set("x-request-id", ids.Request)
		w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("X-Accel-Buffering", "no")
		return nil
	}
	meta := telemetry.MetaFromContext(parent)
	if stream {
		if meta != nil {
			meta.Stream = true
		}
		if g.monitor != nil {
			g.monitor.BeginStream()
			defer g.monitor.EndStream()
		}
		streamBody := wire.RenameStreamReader(resp.Body, route.Protocol, toolRenames)
		usage, reported, committed, err := wire.RotationStream(original.Context(), w, streamBody, route.Protocol, external, alias, ready)
		if meta != nil {
			meta.Usage = usage
			meta.UsageReported = reported
		}
		result.err = err
		result.committed = committed
		result.reason = "stream_error"
		var failure *wire.StreamFailure
		if errors.As(err, &failure) {
			result.quota = quotaError(0, failure.Type+" "+failure.Message)
		}
		if result.quota {
			result.reason = "quota_or_rate_limit"
		} else if !committed && ctx.Err() != nil {
			result.reason = "first_output_timeout"
		}
		return result
	}
	b, err := io.ReadAll(io.LimitReader(resp.Body, (64<<20)+1))
	if err == nil && len(b) > 64<<20 {
		err = errors.New("response exceeds size limit")
	}
	if err != nil {
		result.err = err
		result.reason = "response_read_error"
		return result
	}
	if !timer.Stop() || ctx.Err() != nil {
		result.err = context.DeadlineExceeded
		result.reason = "first_output_timeout"
		return result
	}
	if shaped {
